('g6_2_sci_u2_L01_basic#1','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'mc','auto','네 병 가운데 향불의 불씨가 커진 병은 어느 것인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"mc","stem":"네 병 가운데 향불의 불씨가 커진 병은 어느 것인가요?","options":[{"t":"산소계 표백제가 든 병","correct":true},{"t":"소금이 든 병","mis":"SC6-2-u2-X01"},{"t":"탄산 칼슘이 든 병","mis":"SC6-2-u2-X01"},{"t":"제빵 소다가 든 병","mis":"SC6-2-u2-X01"}],"explanation":["결과 표를 읽어요.","꺼진 병이 셋이에요.","커진 병은 산소계 표백제예요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb),
('g6_2_sci_u2_L01_basic#2','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'mc','auto','고른 유리병에는 무엇을 넣나요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":2,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"mc","stem":"고른 유리병에는 무엇을 넣나요?","options":[{"t":"가루가 잠길 정도의 따뜻한 물","correct":true},{"t":"얼음이 뜰 만큼 차가운 물","mis":"SC6-2-u2-X02"},{"t":"병에 가득 찰 만큼의 기름","mis":"SC6-2-u2-X02"},{"t":"아무것도 넣지 않는다","mis":"SC6-2-u2-X02"}],"explanation":["순서 ②를 읽어요.","가루가 잠길 정도예요.","따뜻한 물이에요."],"asset":{"type":"passage","lines":["① 네 가지 가루가 든 유리병 가운데 하나를 고른다.","② 가루가 잠길 만큼 따뜻한 물을 넣는다.","③ 뚜껑을 닫고 흔든 뒤 잠시 둔다.","④ 뚜껑을 열고 작은 불씨만 남은 향을 병 안에 넣는다.","⑤ 불씨를 살린 것이 무엇인지 이야기한다."],"title":"불씨가 살아나는 병 찾기 순서"}}'::jsonb),
('g6_2_sci_u2_L01_basic#3','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'ox','auto','소금이 든 병에 향불을 넣으면 불씨가 커져요.',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"ox","stem":"소금이 든 병에 향불을 넣으면 불씨가 커져요.","answer":"X","reason_options":[{"t":"소금 병에서는 향불의 불씨가 꺼졌기 때문에","correct":true},{"t":"네 병은 모두 불씨를 살리기 때문에","mis":"SC6-2-u2-X01"}],"mis":"SC6-2-u2-X01","explanation":["소금 병 결과를 떠올려요.","불씨가 꺼졌어요.","커지지 않아요."]}'::jsonb),
('g6_2_sci_u2_L01_basic#4','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',1,'sa','auto','향에 불을 붙일 때 쓰는 도구는 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u2-C1","difficulty":1,"kind":"sa","stem":"향에 불을 붙일 때 쓰는 도구는 무엇인가요? 세 글자로 쓰세요.","answer":["점화기"],"explanation":["불을 붙이는 도구예요.","□화기예요.","점화기예요."],"mis":"SC6-2-u2-X02"}'::jsonb),
('g6_2_sci_u2_L01_basic#5','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'mc','auto','향은 어떤 상태일 때 병 안에 넣나요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":5,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"mc","stem":"향은 어떤 상태일 때 병 안에 넣나요?","options":[{"t":"향 끝에 작은 불씨만 남아 있을 때","correct":true},{"t":"큰 불꽃이 활활 타오를 때","mis":"SC6-2-u2-X02"},{"t":"불을 붙이지 않았을 때","mis":"SC6-2-u2-X02"},{"t":"향불을 완전히 끈 뒤","mis":"SC6-2-u2-X02"}],"explanation":["꺼져 가는 불씨를 살리는 활동이에요.","불꽃이 크면 비교가 안 돼요.","작은 불씨일 때예요."]}'::jsonb),
('g6_2_sci_u2_L01_basic#6','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'match','auto','준비물과 활동에서 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"match","stem":"준비물과 활동에서 하는 일을 알맞게 이으세요.","pairs":[{"l":"유리병","r":"가루 물질이 담겨 있다"},{"l":"따뜻한 물","r":"가루가 잠길 정도로 넣는다"},{"l":"향과 점화기","r":"불씨를 병 안에 넣어 본다"},{"l":"면장갑","r":"불을 다룰 때 화상을 막는다"}],"mis":"SC6-2-u2-X02","explanation":["담는 것은 병이에요.","넣는 것은 물이에요.","불과 보호를 가려요."]}'::jsonb),
('g6_2_sci_u2_L01_basic#7','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'ox','auto','어떤 가루인지 알아보려고 조금 맛을 보아도 괜찮아요.',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":7,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"ox","stem":"어떤 가루인지 알아보려고 조금 맛을 보아도 괜찮아요.","answer":"X","reason_options":[{"t":"실험에 쓰는 물질은 맛보지 않아야 하기 때문에","correct":true},{"t":"맛을 보아야 결과를 정확히 알 수 있기 때문에","mis":"SC6-2-u2-X02"}],"mis":"SC6-2-u2-X02","explanation":["실험 물질이에요.","먹으면 위험해요.","맛보지 않아요."]}'::jsonb),
('g6_2_sci_u2_L01_basic#8','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'error','auto','활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"error","stem":"활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「점화기는 친구가 있는 쪽으로 향해도 돼.」","correct":true,"mis_target":"SC6-2-u2-X02"},{"t":"도윤 — 「불을 다룰 때는 면장갑을 껴.」","mis":"SC6-2-u2-X02"},{"t":"하린 — 「다 쓴 향불은 꼭 끄자.」","mis":"SC6-2-u2-X02"}],"explanation":["점화기 방향을 떠올려요.","사람 쪽은 위험해요.","지안이 잘못 말했어요."]}'::jsonb),
('g6_2_sci_u2_L01_basic#9','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',2,'blank','auto','「유리병에 따뜻한 물을 넣고 (    ) 흔든 뒤 잠시 둡니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"blank","stem":"「유리병에 따뜻한 물을 넣고 (    ) 흔든 뒤 잠시 둡니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"뚜껑을 닫고","correct":true},{"t":"향불을 넣고","mis":"SC6-2-u2-X02"},{"t":"물을 버리고","mis":"SC6-2-u2-X02"},{"t":"병을 깨뜨리고","mis":"SC6-2-u2-X02"}],"explanation":["순서 ③이에요.","흔들려면 막아야 해요.","뚜껑을 닫아요."],"asset":{"type":"passage","lines":["① 네 가지 가루가 든 유리병 가운데 하나를 고른다.","② 가루가 잠길 만큼 따뜻한 물을 넣는다.","③ 뚜껑을 닫고 흔든 뒤 잠시 둔다.","④ 뚜껑을 열고 작은 불씨만 남은 향을 병 안에 넣는다.","⑤ 불씨를 살린 것이 무엇인지 이야기한다."],"title":"불씨가 살아나는 병 찾기 순서"}}'::jsonb),
('g6_2_sci_u2_L01_basic#10','sci',6,2,'u2','L01','g6_2_sci_u2_L01_basic','lesson_basic','SC6-2-u2-C1',3,'mc','auto','네 병에 모두 같은 따뜻한 물을 넣었는데 한 병에서만 불씨가 커졌어요. 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u2-X01']::text[],false,'{"seq":10,"concept":"SC6-2-u2-C1","difficulty":3,"kind":"mc","stem":"네 병에 모두 같은 따뜻한 물을 넣었는데 한 병에서만 불씨가 커졌어요. 알 수 있는 것은 어느 것인가요?","options":[{"t":"따뜻한 물이 아니라 병 속 물질에 따라 결과가 달랐다","correct":true},{"t":"따뜻한 물이 불씨를 살렸다","mis":"SC6-2-u2-X01"},{"t":"네 물질 모두 불씨를 살린다","mis":"SC6-2-u2-X01"},{"t":"병을 흔드는 횟수가 결과를 정했다","mis":"SC6-2-u2-X01"}],"explanation":["같게 한 것과 다른 것을 가려요.","물은 네 병이 같아요.","다른 것은 물질뿐이에요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"}}'::jsonb),
('g6_2_sci_u2_L01_challenge#1','sci',6,2,'u2','L01','g6_2_sci_u2_L01_challenge','lesson_challenge','SC6-2-u2-C1',2,'sa','auto','꺼져 가는 향불의 불씨를 크게 만든 가루는 무엇인가요? (□□□ 표백제)','{}'::text[],false,'{"seq":1,"concept":"SC6-2-u2-C1","difficulty":2,"kind":"sa","stem":"꺼져 가는 향불의 불씨를 크게 만든 가루는 무엇인가요? (□□□ 표백제)","answer":["산소계","산소계 표백제"],"explanation":["불씨가 커진 병이에요.","세 글자예요.","산소계 표백제예요."],"asset":{"type":"passage","lines":["소금 병 — 향불의 불씨가 꺼졌다.","탄산 칼슘 병 — 향불의 불씨가 꺼졌다.","제빵 소다 병 — 향불의 불씨가 꺼졌다.","산소계 표백제 병 — 향불의 불씨가 커졌다.","네 병에는 모두 같은 따뜻한 물을 넣었다."],"title":"네 병에 향불을 넣은 결과"},"mis":"SC6-2-u2-X01"}'::jsonb),
