('g6_2_sci_u2_L05_challenge#3','sci',6,2,'u2','L05','g6_2_sci_u2_L05_challenge','lesson_challenge','SC6-2-u2-C9',3,'error','auto','두 실험의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u2-X20']::text[],false,'{"seq":3,"concept":"SC6-2-u2-C9","difficulty":3,"kind":"error","stem":"두 실험의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「석회수가 흐려졌으니 물이 생긴 거야.」","correct":true,"mis_target":"SC6-2-u2-X20"},{"t":"건우 — 「염화 코발트 종이가 붉게 변했으니 물이 생겼어.」","mis":"SC6-2-u2-X20"},{"t":"유진 — 「석회수가 흐려졌으니 이산화 탄소가 생겼어.」","mis":"SC6-2-u2-X20"}],"explanation":["두 지시약이 알려 주는 것이 달라요.","석회수는 이산화 탄소예요.","수아가 잘못 말했어요."],"asset":{"type":"passage","lines":["실험 1 — 통 안쪽에 붙인 푸른색 염화 코발트 종이가 붉은색으로 변했다.","　　셀로판테이프를 붙인 자리는 푸른색 그대로였다.","실험 2 — 촛불이 꺼진 뒤 뚜껑을 닫고 흔들자","　　무색투명하던 석회수가 뿌옇게 흐려졌다."],"title":"양초가 연소한 뒤 확인한 결과"}}'::jsonb),
