('g6_2_sci_u3_review_d#18','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C9',3,'error','auto','전지 두 개를 이은 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X14','SC6-2-u3-X16']::text[],false,'{"seq":18,"concept":"SC6-2-u3-C9","difficulty":3,"kind":"error","stem":"전지 두 개를 이은 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하민 — 「(−)극끼리 맞대었으니 직렬연결이야.」","correct":true,"mis_target":"SC6-2-u3-X14"},{"t":"수호 — 「한 전지 (+)극에 다른 전지 (−)극을 이었어.」","mis":"SC6-2-u3-X14"},{"t":"다솜 — 「직렬로 이으니 바람개비가 빨라졌어.」","mis":"SC6-2-u3-X16"}],"explanation":["같은 극끼리예요.","직렬연결이 아니에요.","하민의 말이 잘못됐어요."]}'::jsonb),
('g6_2_sci_u3_review_d#19','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C15',3,'error','auto','전자석의 성질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X21','SC6-2-u3-X20','SC6-2-u3-X19']::text[],false,'{"seq":19,"concept":"SC6-2-u3-C15","difficulty":3,"kind":"error","stem":"전자석의 성질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태희 — 「전지 방향을 바꿔도 전자석의 극은 그대로야.」","correct":true,"mis_target":"SC6-2-u3-X21"},{"t":"규리 — 「전지를 더 이으면 클립이 더 붙어.」","mis":"SC6-2-u3-X20"},{"t":"현수 — 「스위치를 닫아야 자석이 돼.」","mis":"SC6-2-u3-X19"}],"explanation":["방향을 바꾸면 극도 바뀌어요.","나침반이 반대를 가리켰어요.","태희의 말이 잘못됐어요."]}'::jsonb),
('g6_2_sci_u3_review_d#20','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C16',3,'error','auto','전자석을 쓰는 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X27','SC6-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC6-2-u3-C16","difficulty":3,"kind":"error","stem":"전자석을 쓰는 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「자석 낚시 놀이도 전자석으로 물고기를 낚아.」","correct":true,"mis_target":"SC6-2-u3-X27"},{"t":"시아 — 「전기 자동차도 전자석으로 바퀴를 돌려.」","mis":"SC6-2-u3-X28"},{"t":"준혁 — 「세탁기는 전자석으로 통을 돌려.」","mis":"SC6-2-u3-X28"}],"explanation":["자석 낚시 놀이는 전기가 없어요.","영구 자석이에요.","은호의 말이 잘못됐어요."]}'::jsonb),
('g6_2_sci_u3_review_d#21','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C20',3,'error','auto','전기 안전을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X37','SC6-2-u3-X34','SC6-2-u3-X36']::text[],false,'{"seq":21,"concept":"SC6-2-u3-C20","difficulty":3,"kind":"error","stem":"전기 안전을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라엘 — 「콘센트 옆에 종이 상자를 쌓아 둬도 괜찮아.」","correct":true,"mis_target":"SC6-2-u3-X37"},{"t":"이든 — 「플러그는 머리 부분을 잡고 뽑아.」","mis":"SC6-2-u3-X34"},{"t":"보미 — 「손을 닦고 플러그를 꽂아.」","mis":"SC6-2-u3-X36"}],"explanation":["타기 쉬운 물건이에요.","치워야 해요.","라엘의 말이 잘못됐어요."]}'::jsonb),
('g6_2_sci_u3_review_d#22','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C22',3,'error','auto','실천 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u3-X39','SC6-2-u3-X40']::text[],false,'{"seq":22,"concept":"SC6-2-u3-C22","difficulty":3,"kind":"error","stem":"실천 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「계획은 크게 세우는 게 좋아. 지키든 못 지키든 상관없어.」","correct":true,"mis_target":"SC6-2-u3-X39"},{"t":"하나 — 「방을 나올 때 전등을 끄기로 했어.」","mis":"SC6-2-u3-X40"},{"t":"윤하 — 「저녁마다 점검표에 표시할 거야.」","mis":"SC6-2-u3-X40"}],"explanation":["지킬 수 있어야 해요.","구체적으로 정해요.","준서의 말이 잘못됐어요."]}'::jsonb),
('g6_2_sci_u3_review_d#23','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C10',4,'essay','teacher','반딧불반 탐구 일지 ③을 보고, 전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로의 특징을 전구·전동기·버저로 견주어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-2-u3-C10","difficulty":4,"kind":"essay","stem":"반딧불반 탐구 일지 ③을 보고, 전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로의 특징을 전구·전동기·버저로 견주어 쓰세요.","answer_guide":{"answer":"예: 전지 두 개를 직렬연결한 회로가 전지 한 개를 이은 회로보다 전구는 더 밝고, 전동기 바람개비는 더 빨리 돌고, 버저 소리는 더 크다.","scoring_points":["전구를 견주었는가","전동기를 견주었는가","버저를 견주었는가"]},"explanation":["세 부품을 봐요.","두 회로를 견줘요.","직렬 쪽이 더 세요."],"asset":{"type":"passage","lines":["전지 한 개를 이은 회로와 전지 두 개를 직렬연결한 회로를 나란히 만들었다.","전지 두 개 쪽 전구가 더 밝았고 전동기 바람개비가 더 빨리 돌았다.","버저는 처음에 울리지 않았는데, 버저 전선을 바꾸어 이으니 크게 울렸다."],"title":"③ 전지 한 개 더 잇기"}}'::jsonb),
('g6_2_sci_u3_review_d#24','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C26',4,'mc','auto','「전기를 아끼는 것」과 「전기를 안전하게 쓰는 것」에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X45','SC6-2-u3-X38']::text[],false,'{"seq":24,"concept":"SC6-2-u3-C26","difficulty":4,"kind":"mc","stem":"「전기를 아끼는 것」과 「전기를 안전하게 쓰는 것」에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"둘은 함께 챙겨야 하며, 아끼려다 안전을 놓치거나 안전하다고 낭비해서는 안 된다","correct":true},{"t":"아끼기만 하면 안전은 저절로 지켜진다","mis":"SC6-2-u3-X45"},{"t":"안전만 지키면 아끼지 않아도 된다","mis":"SC6-2-u3-X45"},{"t":"둘 다 어른만 챙기면 된다","mis":"SC6-2-u3-X38"}],"explanation":["둘 다 중요해요.","하나만 챙기면 안 돼요.","함께 지켜요."]}'::jsonb),
('g6_2_sci_u3_review_d#25','sci',6,2,'u3','','g6_2_sci_u3_review_d','unit_review','SC6-2-u3-C25',4,'mc','auto','토론을 마친 뒤 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u3-X44','SC6-2-u3-X43']::text[],false,'{"seq":25,"concept":"SC6-2-u3-C25","difficulty":4,"kind":"mc","stem":"토론을 마친 뒤 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 쪽 근거에서 새로 알게 된 점을 정리하고, 내 생각을 다시 다듬는다","correct":true},{"t":"이긴 쪽만 옳다고 정리한다","mis":"SC6-2-u3-X44"},{"t":"상대 쪽 근거는 무시하고 내 주장만 되풀이한다","mis":"SC6-2-u3-X44"},{"t":"인공지능은 전기와 상관없다고 정리한다","mis":"SC6-2-u3-X43"}],"explanation":["상대 근거도 봐요.","새로 안 점을 정리해요.","내 생각을 다듬어요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO6-2-u1-C1','soc',6,2,'u1',1,'세계의 다양한 지형과 지형 경관 — 세계에는 산지·하천·해안·사막 등 다양한 지형이 있고, 같은 갈래의 지형도 저마다 독특한 경관 특징이 있으며(피오르·아치 바위·화산·위가 평평한 산 등), 지형 경관은 그곳 사람들의 생활 모습에 영향을 줌 · 조사는 인터넷 조사 → 정리 → 소개 자료 → 발표',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],1),
('SO6-2-u1-C2','soc',6,2,'u1',2,'산지 지형과 생활 모습 — 산지는 해발 고도가 높고 대체로 경사가 급하지만 고원처럼 넓고 평평한 곳, 정상이 움푹 파이거나 물이 고인 화산도 있으며, 사람들은 계단식 농사·가축 기르기·광업·관광(스키장·휴양림·화산 관광)으로 산지를 이용함',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],2),
('SO6-2-u1-C3','soc',6,2,'u1',3,'하천 지형과 생활 모습 — 하천을 따라 계곡·넓은 평야·거대한 폭포가 나타나고, 사람들은 어업·평야의 큰 규모 농사·수력 발전·폭포 관광·물건을 나르고 사고파는 수상 시장으로 하천을 이용함(강이 나른 흙이 쌓여 평야)',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],3),
('SO6-2-u1-C4','soc',6,2,'u1',4,'해안 지형과 생활 모습 — 바다와 육지가 만나는 해안에는 갯벌·모래사장·절벽·돌기둥이 나타나고, 사람들은 어업·양식업을 하며 배가 드나들기 좋은 곳에 항구, 경관이 아름다운 곳에 관광지, 갯벌이 넓은 곳에 염전을 둠 · 관광은 일자리·소득과 쓰레기·오염을 함께 늘림',ARRAY['6사 지리 — 세계의 지형 경관과 생활(초안)']::text[],4),
('SO6-2-u1-C5','soc',6,2,'u1',6,'기후의 뜻과 세계의 기후 분포 — 기후는 한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태(날씨와 다름)이고, 위도뿐 아니라 위치·지형·해발 고도에 따라 달라지며, 기온과 강수량을 기준으로 열대·건조·온대·냉대·한대·고산 기후로 나눔 — 적도에서 극으로 열대→건조→온대→냉대→한대, 적도를 기준으로 남북이 비슷(냉대는 주로 북반구), 매우 높은 산지는 고산, 우리나라는 온대·냉대',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],5),
('SO6-2-u1-C6','soc',6,2,'u1',7,'열대 기후와 생활 모습 — 적도 주변 저위도, 일 년 내내 기온이 높고 기온 변화가 거의 없음, 비가 많아 열대 우림이 되거나 건기·우기가 번갈아 초원이 펼쳐짐 · 화전 농업(카사바·얌·옥수수), 천연고무·카카오·바나나·커피 대규모 재배, 생태 관광, 바람이 통하는 큰 창·바닥을 띄운 고상 가옥·얇은 옷',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],6),
('SO6-2-u1-C7','soc',6,2,'u1',7,'건조 기후와 생활 모습 — 저위도·중위도의 강수량이 적은 곳, 낮과 밤의 기온 차이가 큼, 사막 또는 약간의 비로 초원 · 햇볕과 모래바람을 막는 온몸을 감싸는 옷, 벽이 두껍고 창이 작은 흙벽돌 집, 오아시스 주변 농사, 초원의 유목 생활과 이동식 가옥',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],7),
('SO6-2-u1-C8','soc',6,2,'u1',8,'온대 기후·냉대 기후와 생활 모습 — 온대는 중위도, 사계절이 비교적 뚜렷, 서부 유럽(여름 서늘·겨울 따뜻·비 고름 — 밀·낙농업)·지중해 주변(여름 덥고 건조·겨울 비 — 올리브·포도)·우리나라(여름 덥고 비·겨울 춥고 건조 — 벼농사) · 냉대는 북반구 중·고위도, 겨울이 여름보다 길고 몹시 추우며 눈이 많음, 여름에 밀·옥수수·감자, 침엽수림으로 목재·펄프 생산',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],8),
('SO6-2-u1-C9','soc',6,2,'u1',9,'한대 기후·고산 기후와 생활 모습 — 한대는 남극·북극 주변 고위도, 겨울이 길고 기온이 매우 낮아 눈과 얼음에 덮인 곳이 많음, 사냥한 생선·고기, 이끼 자라는 곳의 순록 유목, 지하자원 개발·극지 연구, 오로라·빙하 관광 · 고산은 해발 고도가 높은 곳, 적도 주변 일부는 일 년 내내 서늘해 사람이 많이 모여 삶, 감자·옥수수, 알파카·라마, 챙 넓은 둥근 모자·여러 겹 옷과 망토로 낮과 밤의 기온 차이에 적응 · 추운 기후로 가는 길은 둘(고위도·고산)',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],9),
('SO6-2-u1-C10','soc',6,2,'u1',10,'기후에 적응·극복하는 생활 조사와 자연환경을 고려한 상품 계획 — 사람들은 기후에 적응하고 이를 극복하며 살아가고 같은 기후에서도 생활 모습은 여러 가지임 · 조사: 주제 정하기 → 인터넷 조사 → 디지털 영상 지도에 표시 → 공유 · 상품 계획: 나라 정하기 → 지형과 기후 조사 → 아이디어 이야기 → 판매 계획 → 글과 그림, 자연환경의 특징을 상품 기능에 담고 실현 가능성도 생각',ARRAY['6사 지리 — 세계의 기후와 생활(초안)']::text[],10)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO6-2-u1-X01','soc',6,'u1',ARRAY['SO6-2-u1-C1']::text[],'세계의 지형은 모두 비슷하거나, 같은 갈래(산지 등)의 지형은 경관 특징도 하나뿐이라고 여긴다','같은 산지라도 — 화산? 위가 평평? 거대한 바위?'),
('SO6-2-u1-X02','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C10']::text[],'지형 경관이나 기후는 그곳 사람들의 생활 모습과 관계가 없다고 여긴다','「그래서 그곳 사람들은 무엇을 하며 살까?」'),
('SO6-2-u1-X03','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C2','SO6-2-u1-C3','SO6-2-u1-C4']::text[],'지형의 갈래(산지·하천·해안·사막)를 헷갈린다(피오르를 하천으로, 수상 시장을 해안으로 등)','바다와 육지가 만나나? 강을 따라가나? 높이 솟았나?'),
('SO6-2-u1-X04','soc',6,'u1',ARRAY['SO6-2-u1-C2']::text[],'산지는 모두 경사가 급해 사람이 살 수 없다고 여기거나, 고원·화산 같은 산지의 여러 모습을 모른다','고원은 넓고 평평 — 가축을 길러요'),
('SO6-2-u1-X05','soc',6,'u1',ARRAY['SO6-2-u1-C3']::text[],'하천 지역의 생활(평야 농사·어업·수력 발전·폭포 관광·수상 시장)을 다른 지형의 생활과 헷갈린다','물이 흐르며 무엇을 주나? 흙·물고기·힘·길'),
('SO6-2-u1-X06','soc',6,'u1',ARRAY['SO6-2-u1-C4']::text[],'해안의 이용을 자리와 맞지 않게 짝짓는다(배가 드나들기 좋은 곳에 염전, 갯벌에 항구 등)','배 → 항구 · 넓은 갯벌 → 염전 · 아름다운 경관 → 관광지'),
('SO6-2-u1-X07','soc',6,'u1',ARRAY['SO6-2-u1-C4','SO6-2-u1-C10']::text[],'관광이나 개발의 한쪽 영향(좋은 점만 또는 나쁜 점만)만 본다','늘어나는 것 둘 — 일자리·소득과 쓰레기·오염'),
('SO6-2-u1-X08','soc',6,'u1',ARRAY['SO6-2-u1-C5']::text[],'기후를 하루나 며칠의 날씨와 같은 것으로 여긴다','여러 해에 걸쳐 되풀이되는 평균 상태'),
('SO6-2-u1-X09','soc',6,'u1',ARRAY['SO6-2-u1-C5','SO6-2-u1-C9']::text[],'기후가 위도만으로 정해진다고 여겨 위치·지형·해발 고도의 영향을 놓친다(적도 주변은 어디나 덥다)','적도 주변이라도 산 위로 오르면?'),
('SO6-2-u1-X10','soc',6,'u1',ARRAY['SO6-2-u1-C5']::text[],'기후 구분의 기준(기온과 강수량)이나 적도에서 극으로 가는 기후의 차례를 헷갈린다','열대 → 건조 → 온대 → 냉대 → 한대'),
('SO6-2-u1-X11','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7']::text[],'열대 기후와 건조 기후의 특징을 헷갈린다(열대는 일교차가 크다, 건조는 비가 많다 등)','열대 — 늘 덥고 비 많음 · 건조 — 비 적고 낮밤 차이 큼'),
('SO6-2-u1-X12','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7']::text[],'기후에 맞춘 집·옷·농업을 다른 기후의 것과 바꾸어 짝짓는다(사막에 고상 가옥, 열대에 두꺼운 벽 등)','그 기후에서 막을 것과 들일 것은?'),
('SO6-2-u1-X13','soc',6,'u1',ARRAY['SO6-2-u1-C8']::text[],'온대 기후와 냉대 기후, 또는 온대 안의 서부 유럽·지중해·우리나라의 특징과 농업을 헷갈린다','겨울이 여름보다 길고 몹시 추우면 냉대'),
('SO6-2-u1-X14','soc',6,'u1',ARRAY['SO6-2-u1-C9']::text[],'한대 기후와 고산 기후를 헷갈리거나, 고산 기후는 극지방에만 있다고 여긴다','고위도로 멀리 → 한대 · 높이 오르면 → 고산'),
('SO6-2-u1-X15','soc',6,'u1',ARRAY['SO6-2-u1-C6','SO6-2-u1-C7','SO6-2-u1-C8','SO6-2-u1-C10']::text[],'한 곳의 생활 모습을 그 기후 전체의 모습으로 여기거나, 같은 기후 지역은 생활이 모두 같다고 여긴다','같은 온대에도 밀·올리브·벼'),
('SO6-2-u1-X16','soc',6,'u1',ARRAY['SO6-2-u1-C10']::text[],'상품을 구상할 때 그곳의 지형·기후를 고려하지 않거나 한 상품이 어디서나 똑같이 쓰인다고 여긴다','그곳 사람들의 불편은 자연환경의 어떤 특징에서 오나?'),
('SO6-2-u1-X17','soc',6,'u1',ARRAY['SO6-2-u1-C1','SO6-2-u1-C10']::text[],'조사·계획의 차례를 헷갈리거나 출처를 확인하지 않고 자료를 쓴다','정하고 → 조사하고 → 정리하고 → 나누기')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_soc_u1_L01_basic#1','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'mc','auto','세계의 지형에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"세계의 지형에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"세계에는 산지·하천·해안·사막 등 다양한 지형이 있다","correct":true},{"t":"세계에는 산지만 있다","mis":"SO6-2-u1-X01"},{"t":"세계의 지형은 어디나 같은 모습이다","mis":"SO6-2-u1-X01"},{"t":"세계에는 바다와 사막만 있다","mis":"SO6-2-u1-X01"}],"explanation":["세계에는 여러 갈래의 지형이 있어요.","산지·하천·해안·사막이 대표적이에요.","지형마다 경관의 특징이 달라요."]}'::jsonb),
('g6_2_soc_u1_L01_basic#2','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'mc','auto','「피오르」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"「피오르」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"빙하가 깎아 만든 유(U) 자 모양 골짜기에 바닷물이 들어와 생긴 해안","correct":true},{"t":"용암이 흘러 굳어서 생긴 화산","mis":"SO6-2-u1-X03"},{"t":"모래 언덕이 끝없이 펼쳐진 땅","mis":"SO6-2-u1-X03"},{"t":"강물이 높은 곳에서 떨어지는 곳","mis":"SO6-2-u1-X03"}],"explanation":["피오르는 빙하가 만든 골짜기예요.","그 골짜기에 바닷물이 들어왔어요.","그래서 가파른 산 사이로 좁고 긴 바다가 보여요."]}'::jsonb),
('g6_2_soc_u1_L01_basic#3','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'ox','auto','지형 경관은 그곳에서 살아가는 사람들의 생활 모습에 영향을 줘요.',ARRAY['SO6-2-u1-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"ox","stem":"지형 경관은 그곳에서 살아가는 사람들의 생활 모습에 영향을 줘요.","answer":"O","reason_options":[{"t":"지형에 따라 농사·일·여행처럼 사람들이 살아가는 방법이 달라지기 때문에","correct":true},{"t":"지형은 자연이고 생활은 사람의 일이라 서로 관계가 없기 때문에","mis":"SO6-2-u1-X02"}],"mis":"SO6-2-u1-X02","explanation":["경관이 아름다운 곳은 여행지가 되기도 해요.","지형에 따라 할 수 있는 일이 달라요.","그래서 지형 경관은 생활 모습에 영향을 줘요."]}'::jsonb),
('g6_2_soc_u1_L01_basic#4','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',1,'sa','auto','세계의 대표적인 지형 네 가지는 산지·하천·해안 그리고 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"sa","stem":"세계의 대표적인 지형 네 가지는 산지·하천·해안 그리고 무엇인가요? 두 글자로 쓰세요.","answer":["사막"],"explanation":["지형은 크게 네 갈래로 나누어 살펴보았어요.","산지·하천·해안·사막이에요.","사하라는 대표적인 사막이에요."],"mis":"SO6-2-u1-X03"}'::jsonb),
('g6_2_soc_u1_L01_basic#5','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'match','auto','지형과 그 지형이 드는 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"match","stem":"지형과 그 지형이 드는 갈래를 알맞게 이으세요.","pairs":[{"l":"송네 피오르","r":"해안"},{"l":"황허강","r":"하천"},{"l":"사하라","r":"사막"},{"l":"마우나로아","r":"산지"}],"mis":"SO6-2-u1-X03","explanation":["피오르는 바다와 육지가 만나는 해안이에요.","황허강은 하천, 사하라는 사막이에요.","마우나로아는 화산이라 산지예요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb),
('g6_2_soc_u1_L01_basic#6','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','일곱 곳 가운데 산지에 드는 세 곳이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"일곱 곳 가운데 산지에 드는 세 곳이 서로 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 산지라도 화산·거대한 바위·위가 평평한 산처럼 서로 다른 특징이 나타나기 때문에","correct":true},{"t":"산지는 한 가지 모습만 있는 지형이기 때문에","mis":"SO6-2-u1-X01"},{"t":"세 곳이 모두 바닷가에 있기 때문에","mis":"SO6-2-u1-X03"},{"t":"세 곳이 같은 나라에 있기 때문에","mis":"SO6-2-u1-X01"}],"explanation":["마우나로아는 용암이 흐르는 화산이에요.","울루루는 하나의 거대한 암석, 호라이마산은 위가 평평해요.","같은 갈래 안에서도 특징이 갈려요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb),
('g6_2_soc_u1_L01_basic#7','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','엘 아르코의 경관 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"엘 아르코의 경관 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"바다 위에 아치 모양의 바위가 솟아 있다","correct":true},{"t":"누런 강물이 굽이쳐 흐른다","mis":"SO6-2-u1-X03"},{"t":"모래 언덕이 끝없이 펼쳐진다","mis":"SO6-2-u1-X03"},{"t":"용암이 흐르는 화산이다","mis":"SO6-2-u1-X03"}],"explanation":["엘 아르코는 바닷가에 있어요.","아치 모양의 바위가 바다 위로 솟아 있어요.","해안 지형의 경관이에요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb),
('g6_2_soc_u1_L01_basic#8','soc',6,2,'u1','L01','g6_2_soc_u1_L01_basic','lesson_basic','SO6-2-u1-C1',2,'mc','auto','세계의 지형 경관과 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":2,"kind":"mc","stem":"세계의 지형 경관과 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"인터넷으로 조사하기 → 조사 내용 정리하기 → 소개 자료 만들기 → 발표하기","correct":true},{"t":"발표하기 → 인터넷으로 조사하기 → 소개 자료 만들기 → 정리하기","mis":"SO6-2-u1-X17"},{"t":"소개 자료 만들기 → 발표하기 → 조사하기 → 정리하기","mis":"SO6-2-u1-X17"},{"t":"정리하기 → 발표하기 → 조사하기 → 소개 자료 만들기","mis":"SO6-2-u1-X17"}],"explanation":["먼저 조사해요.","조사한 것을 정리해 소개 자료로 만들어요.","그다음 친구들 앞에서 발표해요."]}'::jsonb),
