('g6_2_soc_u1_L01_challenge#6','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'error','auto','세계의 지형 경관 소개 자료를 만들며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"세계의 지형 경관 소개 자료를 만들며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하준 — 「누가 올렸는지 몰라도 사진이 멋지면 그대로 써.」","correct":true,"mis_target":"SO6-2-u1-X17"},{"t":"예나 — 「조사한 내용을 정리표에 담고 그걸로 소개 자료를 만들자.」","mis":"SO6-2-u1-X17"},{"t":"도현 — 「자료를 찾은 곳을 소개 자료 끝에 적어 두자.」","mis":"SO6-2-u1-X17"}],"explanation":["조사 자료는 믿을 만한 곳에서 찾아요.","찾은 곳(출처)을 적어 두어요.","예나와 도현은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_L01_challenge#7','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',3,'match','auto','지형과 그 경관 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"match","stem":"지형과 그 경관 특징을 알맞게 이으세요.","pairs":[{"l":"호라이마산","r":"우뚝 솟았지만 위쪽이 평평하다"},{"l":"울루루","r":"하나의 거대한 암석이 평지에 솟아 있다"},{"l":"마우나로아","r":"용암이 흐르는 화산이다"},{"l":"사하라","r":"모래 언덕이 끝없이 펼쳐진다"}],"mis":"SO6-2-u1-X01","explanation":["같은 산지라도 특징이 달라요.","호라이마산·울루루·마우나로아는 모두 산지예요.","사하라는 사막이에요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb),
('g6_2_soc_u1_L01_challenge#8','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'mc','auto','일곱 곳을 산지·하천·해안·사막으로 나눈 뒤 「한 칸에 여럿이 모인 자리」가 생겼어요. 이 자리를 더 가를 수 있는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"mc","stem":"일곱 곳을 산지·하천·해안·사막으로 나눈 뒤 「한 칸에 여럿이 모인 자리」가 생겼어요. 이 자리를 더 가를 수 있는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 칸에 모인 곳들이 서로 다르게 답할 특징 물음을 댄다","correct":true},{"t":"모두에게 같은 답이 나오는 물음을 계속 댄다","mis":"SO6-2-u1-X01"},{"t":"칸 이름을 더 길게 바꾼다","mis":"SO6-2-u1-X03"},{"t":"한 칸에 모인 곳은 모두 같은 지형이니 그대로 둔다","mis":"SO6-2-u1-X01"}],"explanation":["답이 같은 물음으로는 갈리지 않아요.","「화산인가요?」, 「위가 평평한가요?」처럼 서로 다르게 답할 물음이 필요해요.","그러면 같은 갈래 안의 다른 특징이 드러나요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb),
('g6_2_soc_u1_L01_challenge#9','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'essay','teacher','송네 피오르와 사하라 사막의 경관 특징을 한 가지씩 쓰고, 두 지형 경관이 그곳 사람들의 생활 모습에 어떤 영향을 줄지 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"essay","stem":"송네 피오르와 사하라 사막의 경관 특징을 한 가지씩 쓰고, 두 지형 경관이 그곳 사람들의 생활 모습에 어떤 영향을 줄지 짐작해 쓰세요.","answer_guide":{"answer":"예: 송네 피오르는 가파른 산 사이로 좁고 긴 바다가 들어와 있고, 사하라 사막은 모래 언덕이 끝없이 펼쳐져 있다. 송네 피오르는 경관이 아름다워 배를 타고 구경하는 관광이 발달할 것 같고, 사하라 사막은 물이 적어 사람들이 물을 찾아 옮겨 다니거나 오아시스 주변에 모여 살 것 같다.","scoring_points":["두 지형의 경관 특징을 한 가지씩 바르게 썼는가","경관이 생활에 영향을 준다는 점을 썼는가","지형마다 알맞은 생활 모습을 짐작했는가"]},"explanation":["지형마다 경관 특징이 달라요.","경관은 생활에 영향을 줘요.","근거를 들어 짐작해요."],"asset":{"type":"passage","lines":["① 송네 피오르(노르웨이) — 가파른 산 사이로 좁고 긴 바다가 들어와 있다","② 엘 아르코(멕시코) — 바다 위에 아치 모양의 바위가 솟아 있다","③ 마우나로아(미국 하와이) — 용암이 흐르는 모습을 볼 수 있는 화산이다","④ 사하라 사막(아프리카 북부) — 모래 언덕이 끝없이 펼쳐져 있다","⑤ 황허강(중국) — 황토가 섞인 누런 강물이 굽이쳐 길게 흐른다","⑥ 울루루(오스트레일리아) — 하나의 거대한 암석이 평지에 솟아 있다","⑦ 호라이마산(베네수엘라 볼리바르) — 우뚝 솟았지만 위쪽이 평평하다"],"title":"세계의 유명한 지형 일곱 곳"}}'::jsonb),
('g6_2_soc_u1_L01_challenge#10','soc',6,2,'u1','L01','g6_2_soc_u1_L01_challenge','lesson_challenge','SO6-2-u1-C1',4,'essay','teacher','세계의 지형 경관 하나를 골라 조사해 소개 자료를 만든다고 할 때, 조사하는 차례를 쓰고 소개 자료에 꼭 넣을 내용을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C1","difficulty":4,"kind":"essay","stem":"세계의 지형 경관 하나를 골라 조사해 소개 자료를 만든다고 할 때, 조사하는 차례를 쓰고 소개 자료에 꼭 넣을 내용을 두 가지 쓰세요.","answer_guide":{"answer":"예: 인터넷으로 조사하기 → 조사 내용 정리하기 → 소개 자료 만들기 → 발표하기의 차례로 한다. 소개 자료에는 그 지형의 경관 특징과 그곳 사람들의 생활 모습을 꼭 넣고, 자료를 찾은 곳도 적는다.","scoring_points":["조사 차례를 바르게 썼는가","경관 특징과 생활 모습을 넣었는가","자료를 찾은 곳(출처)을 생각했는가"]},"explanation":["조사 → 정리 → 소개 자료 → 발표예요.","경관과 생활을 함께 담아요.","출처도 적어요."]}'::jsonb),
('g6_2_soc_u1_L02_basic#1','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'mc','auto','산지 지형의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"산지 지형의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"해발 고도가 높고 대체로 경사가 급하다","correct":true},{"t":"바다와 육지가 만나는 곳이다","mis":"SO6-2-u1-X03"},{"t":"모래 언덕이 끝없이 펼쳐진다","mis":"SO6-2-u1-X03"},{"t":"강물이 흙을 날라 넓은 평야가 생긴다","mis":"SO6-2-u1-X03"}],"explanation":["산지는 높이 솟은 땅이에요.","대체로 경사가 급해요.","바다와 만나는 곳은 해안, 흙이 쌓인 평야는 하천 지형이에요."]}'::jsonb),
('g6_2_soc_u1_L02_basic#2','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'sa','auto','바다 표면으로부터 잰 육지의 높이를 무엇이라고 하나요? 「해발 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"sa","stem":"바다 표면으로부터 잰 육지의 높이를 무엇이라고 하나요? 「해발 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["고도"],"explanation":["산지는 해발 고도가 높아요.","해발 고도는 바다 표면을 기준으로 재요.","고산 기후를 배울 때도 쓰여요."],"mis":"SO6-2-u1-X04"}'::jsonb),
('g6_2_soc_u1_L02_basic#3','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'ox','auto','산지에는 경사가 급한 곳만 있어요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"ox","stem":"산지에는 경사가 급한 곳만 있어요.","answer":"X","reason_options":[{"t":"고원처럼 비교적 넓고 평평한 곳도 있고, 정상이 움푹 파인 화산도 있기 때문에","correct":true},{"t":"산지는 모두 뾰족한 봉우리로만 되어 있기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["산지는 대체로 경사가 급해요.","하지만 고원처럼 넓고 평평한 곳도 있어요.","화산은 정상이 움푹 파이거나 물이 고이기도 해요."]}'::jsonb),
('g6_2_soc_u1_L02_basic#4','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',1,'mc','auto','세계의 유명한 산지 지형이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C2","difficulty":1,"kind":"mc","stem":"세계의 유명한 산지 지형이 아닌 것은 어느 것인가요?","options":[{"t":"나일강","correct":true},{"t":"히말라야산맥","mis":"SO6-2-u1-X03"},{"t":"알프스산맥","mis":"SO6-2-u1-X03"},{"t":"파미르고원","mis":"SO6-2-u1-X03"}],"explanation":["히말라야·알프스는 큰 산맥이에요.","파미르고원도 산지예요.","나일강은 하천 지형이에요."]}'::jsonb),
('g6_2_soc_u1_L02_basic#5','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'match','auto','산지와 그곳 사람들의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"match","stem":"산지와 그곳 사람들의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"파미르고원(타지키스탄)","r":"평탄한 땅의 풀로 양을 기른다"},{"l":"알프스산맥(스위스)","r":"아름다운 경관으로 관광지가 발달했다"},{"l":"추키카마타(칠레)","r":"구리를 캐는 광업이 발달했다"},{"l":"아이슬란드","r":"화산 분출을 보는 곳을 관광지로 쓴다"}],"mis":"SO6-2-u1-X02","explanation":["산지의 모습에 따라 생활이 달라요.","평탄한 고원은 가축, 아름다운 경관은 관광이에요.","지하자원이 많으면 광업이 발달해요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb),
('g6_2_soc_u1_L02_basic#6','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','산지의 경사가 가파른 곳에서 농사짓는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X05','SO6-2-u1-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"산지의 경사가 가파른 곳에서 농사짓는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"산비탈을 계단처럼 깎아 계단식 농사를 짓는다","correct":true},{"t":"대형 농기계로 넓은 평야를 한꺼번에 간다","mis":"SO6-2-u1-X05"},{"t":"갯벌에 바닷물을 가두어 소금을 만든다","mis":"SO6-2-u1-X06"},{"t":"비행기로 씨를 뿌려 넓은 밭을 가꾼다","mis":"SO6-2-u1-X05"}],"explanation":["가파른 땅은 그대로 농사짓기 어려워요.","비탈을 계단처럼 만들면 평평한 땅이 생겨요.","사람들은 지형을 이용해 살아가요."]}'::jsonb),
('g6_2_soc_u1_L02_basic#7','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'mc','auto','칠레 추키카마타에서 광업이 발달한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02','SO6-2-u1-X05','SO6-2-u1-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"칠레 추키카마타에서 광업이 발달한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"땅속에 구리가 많이 묻혀 있기 때문에","correct":true},{"t":"경치가 아름다워 관광객이 많기 때문에","mis":"SO6-2-u1-X02"},{"t":"넓은 평야가 펼쳐져 있기 때문에","mis":"SO6-2-u1-X05"},{"t":"바다와 가까워 항구가 있기 때문에","mis":"SO6-2-u1-X06"}],"explanation":["지하자원이 풍부한 산지에서는 광업이 발달해요.","추키카마타는 구리 매장량이 많아요.","산지의 이용은 그 땅이 가진 것에 따라 달라요."],"asset":{"type":"passage","lines":["㉠ 타지키스탄 파미르고원 — 땅이 비교적 평탄하고 풀이 잘 자란다","㉡ 스위스 알프스산맥 — 눈 덮인 봉우리와 호수가 아름답다","㉢ 칠레 추키카마타 — 땅속에 구리가 많이 묻혀 있다","㉣ 아이슬란드 — 화산이 분출하는 모습을 가까이서 볼 수 있다"],"title":"산지 네 곳"}}'::jsonb),
('g6_2_soc_u1_L02_basic#8','soc',6,2,'u1','L02','g6_2_soc_u1_L02_basic','lesson_basic','SO6-2-u1-C2',2,'ox','auto','산지의 아름다운 지형 경관은 스키장이나 휴양림 같은 관광지로 이용되기도 해요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"ox","stem":"산지의 아름다운 지형 경관은 스키장이나 휴양림 같은 관광지로 이용되기도 해요.","answer":"O","reason_options":[{"t":"사람들이 아름다운 경관을 즐기러 찾아와 관광이 발달하기 때문에","correct":true},{"t":"산지에는 사람이 찾아가지 않기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["알프스산맥은 관광지로 유명해요.","스키장·휴양림도 산지를 이용한 곳이에요.","화산도 관광지가 되기도 해요."]}'::jsonb),
