('g6_2_soc_u1_L04_challenge#8','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'mc','auto','관광이 늘어난 섬 사람들이 할 수 있는 결정으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"mc","stem":"관광이 늘어난 섬 사람들이 할 수 있는 결정으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"관광으로 생긴 일자리와 오염을 함께 따져, 쓰레기를 줄이는 규칙을 정하고 관광객 수를 알맞게 조절한다","correct":true},{"t":"일자리가 늘었으니 오염은 생각하지 않는다","mis":"SO6-2-u1-X07"},{"t":"오염이 생겼으니 관광을 영원히 금지한다","mis":"SO6-2-u1-X07"},{"t":"관광은 해안과 관계가 없으니 그대로 둔다","mis":"SO6-2-u1-X02"}],"explanation":["관광에는 좋은 점과 걱정이 함께 있어요.","한쪽만 보면 다른 쪽 문제가 커져요.","둘을 함께 따져 결정해요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_L04_challenge#9','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'essay','teacher','해안 사람들이 해안을 이용하는 방법을 세 가지 쓰고, 각각 어떤 해안에서 발달하는지 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"해안 사람들이 해안을 이용하는 방법을 세 가지 쓰고, 각각 어떤 해안에서 발달하는지 함께 쓰세요.","answer_guide":{"answer":"예: 배가 드나들기에 유리한 해안에서는 항구를 만들어 배가 오가게 한다. 갯벌이 넓게 펼쳐진 해안에서는 염전을 만들어 소금을 얻는다. 경관이 아름다운 해안은 관광지로 이용한다. 이 밖에 어업과 양식업도 한다.","scoring_points":["해안 이용 방법을 세 가지 썼는가","각각 발달하는 해안의 모습을 바르게 짝지었는가","해안의 모습이 생활을 정한다는 점이 드러나는가"]},"explanation":["해안의 모습을 먼저 봐요.","배·갯벌·경관을 떠올려요.","항구·염전·관광지예요."]}'::jsonb),
('g6_2_soc_u1_L04_challenge#10','soc',6,2,'u1','L04','g6_2_soc_u1_L04_challenge','lesson_challenge','SO6-2-u1-C4',4,'essay','teacher','어느 해안 마을에 관광객이 많이 찾아오게 되었어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 마을이 할 수 있는 일을 한 가지 제안하세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"어느 해안 마을에 관광객이 많이 찾아오게 되었어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 마을이 할 수 있는 일을 한 가지 제안하세요.","answer_guide":{"answer":"예: 긍정적인 영향 — 숙소·식당·안내 일자리가 생겨 마을 사람들의 소득이 늘어난다. 부정적인 영향 — 바닷가에 쓰레기가 쌓이고 바닷물이 오염된다. 제안 — 관광객에게 쓰레기를 되가져가게 하고, 해마다 일정한 기간은 바닷가를 쉬게 한다.","scoring_points":["긍정적인 영향을 썼는가","부정적인 영향을 썼는가","두 영향을 함께 고려한 제안을 했는가"]},"explanation":["관광은 두 가지 영향을 함께 줘요.","한쪽만 보지 않아요.","둘을 따져 방법을 찾아요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_L06_basic#1','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'mc','auto','기후의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"기후의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 지역에서 여러 해에 걸쳐 되풀이되는 대기의 평균 상태","correct":true},{"t":"하루 동안 잠깐 나타나는 날씨","mis":"SO6-2-u1-X08"},{"t":"바다 표면으로부터 잰 육지의 높이","mis":"SO6-2-u1-X09"},{"t":"지구의 남쪽과 북쪽을 나누는 선","mis":"SO6-2-u1-X10"}],"explanation":["기후는 오랜 기간의 평균 상태예요.","오늘 비가 오는 것은 날씨예요.","해발 고도·적도와는 다른 말이에요."]}'::jsonb),
('g6_2_soc_u1_L06_basic#2','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'mc','auto','세계의 기후를 구분하는 주된 기준 두 가지는 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계의 기후를 구분하는 주된 기준 두 가지는 어느 것인가요?","options":[{"t":"기온과 강수량","correct":true},{"t":"나라 이름과 인구","mis":"SO6-2-u1-X10"},{"t":"산의 높이와 강의 길이","mis":"SO6-2-u1-X10"},{"t":"바람의 색과 구름의 모양","mis":"SO6-2-u1-X10"}],"explanation":["기후는 주로 기온과 강수량으로 나눠요.","얼마나 덥고 추운지, 비가 얼마나 오는지 봐요.","나라 이름은 기준이 아니에요."]}'::jsonb),
('g6_2_soc_u1_L06_basic#3','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'sa','auto','매우 높은 산지에서 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"sa","stem":"매우 높은 산지에서 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["고산"],"explanation":["높이 올라갈수록 기온이 낮아져요.","매우 높은 산지에는 고산 기후가 나타나요.","위도의 차례와 다르게 놓여요."],"mis":"SO6-2-u1-X09"}'::jsonb),
('g6_2_soc_u1_L06_basic#4','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',1,'ox','auto','우리나라에서 나타나는 기후는 온대 기후와 냉대 기후예요.',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"ox","stem":"우리나라에서 나타나는 기후는 온대 기후와 냉대 기후예요.","answer":"O","reason_options":[{"t":"우리나라는 중위도에 있어 사계절이 나타나는 온대 기후와 냉대 기후가 나타나기 때문에","correct":true},{"t":"우리나라는 적도 바로 위에 있기 때문에","mis":"SO6-2-u1-X10"}],"mis":"SO6-2-u1-X10","explanation":["우리나라는 중위도에 있어요.","사계절이 뚜렷해요.","온대 기후와 냉대 기후가 나타나요."]}'::jsonb),
('g6_2_soc_u1_L06_basic#5','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','적도에서 극지방으로 가면서 나타나는 기후의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"적도에서 극지방으로 가면서 나타나는 기후의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"열대 → 건조 → 온대 → 냉대 → 한대","correct":true},{"t":"한대 → 냉대 → 온대 → 건조 → 열대","mis":"SO6-2-u1-X10"},{"t":"열대 → 온대 → 건조 → 한대 → 냉대","mis":"SO6-2-u1-X10"},{"t":"건조 → 열대 → 냉대 → 온대 → 한대","mis":"SO6-2-u1-X10"}],"explanation":["적도 주변은 열대 기후예요.","극으로 갈수록 건조 → 온대 → 냉대 → 한대예요.","극지방에는 한대 기후가 나타나요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb),
('g6_2_soc_u1_L06_basic#6','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'ox','auto','세계의 기후는 위도만으로 정해져요.',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"세계의 기후는 위도만으로 정해져요.","answer":"X","reason_options":[{"t":"위도뿐 아니라 위치·지형·해발 고도에 따라서도 다르게 나타나기 때문에","correct":true},{"t":"같은 위도에서는 언제나 같은 기후가 나타나기 때문에","mis":"SO6-2-u1-X09"}],"mis":"SO6-2-u1-X09","explanation":["위도는 기후에 큰 영향을 줘요.","하지만 위치·지형·해발 고도도 영향을 줘요.","적도 주변의 높은 산에는 고산 기후가 나타나요."]}'::jsonb),
('g6_2_soc_u1_L06_basic#7','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','북쪽에 기후 띠를 쌓을 때 남쪽에도 같은 차례로 띠가 나타난 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"북쪽에 기후 띠를 쌓을 때 남쪽에도 같은 차례로 띠가 나타난 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후가 위도에 따라 달라지고 적도를 기준으로 남북이 비슷하게 나타나기 때문에","correct":true},{"t":"남쪽과 북쪽은 늘 반대 기후가 나타나기 때문에","mis":"SO6-2-u1-X10"},{"t":"남쪽에는 기후가 없기 때문에","mis":"SO6-2-u1-X10"},{"t":"기후는 나라마다 아무렇게나 정해지기 때문에","mis":"SO6-2-u1-X10"}],"explanation":["적도를 기준으로 남북을 견주어 봐요.","같은 위도에는 비슷한 기후가 나타나요.","다만 냉대 기후는 주로 북반구에 나타나요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb),
('g6_2_soc_u1_L06_basic#8','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'match','auto','「날씨」와 「기후」를 쓴 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"match","stem":"「날씨」와 「기후」를 쓴 문장을 알맞게 이으세요.","pairs":[{"l":"오늘은 비가 오고 바람이 세다.","r":"날씨 — 짧은 기간의 대기 상태"},{"l":"이 지역은 해마다 여름에 덥고 비가 많다.","r":"기후 — 여러 해의 평균 상태"}],"mis":"SO6-2-u1-X08","explanation":["날씨는 짧은 기간의 대기 상태예요.","기후는 여러 해의 평균 상태예요.","「해마다」는 기후를 알려 주는 말이에요."]}'::jsonb),
('g6_2_soc_u1_L06_basic#9','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',2,'mc','auto','기후 분포에 영향을 주는 요인이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"기후 분포에 영향을 주는 요인이 아닌 것은 어느 것인가요?","options":[{"t":"그 나라의 국기 색깔","correct":true},{"t":"위도","mis":"SO6-2-u1-X09"},{"t":"해발 고도","mis":"SO6-2-u1-X09"},{"t":"지형","mis":"SO6-2-u1-X09"}],"explanation":["위도·위치·지형·해발 고도가 기후에 영향을 줘요.","국기 색깔은 기후와 관계가 없어요.","여러 요인을 함께 봐요."]}'::jsonb),
('g6_2_soc_u1_L06_basic#10','soc',6,2,'u1','L06','g6_2_soc_u1_L06_basic','lesson_basic','SO6-2-u1-C5',3,'error','auto','세계의 기후 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X10']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"세계의 기후 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「적도 주변은 어디든 덥기만 하니까 서늘한 기후는 없어.」","correct":true,"mis_target":"SO6-2-u1-X09"},{"t":"지안 — 「적도 주변이라도 매우 높은 산지에는 고산 기후가 나타나.」","mis":"SO6-2-u1-X09"},{"t":"하율 — 「극지방에는 한대 기후가 주로 나타나.」","mis":"SO6-2-u1-X10"}],"explanation":["적도 주변이라도 해발 고도가 높으면 서늘해요.","그래서 고산 기후가 나타나요.","지안과 하율은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_L06_challenge#1','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',2,'sa','auto','세계의 기후는 열대·건조·온대·냉대·한대·고산 기후로 나눠요. 남극과 북극 주변에 주로 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"sa","stem":"세계의 기후는 열대·건조·온대·냉대·한대·고산 기후로 나눠요. 남극과 북극 주변에 주로 나타나는 기후는 무엇인가요? 「○○ 기후」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["한대"],"explanation":["극지방은 기온이 매우 낮아요.","한대 기후가 나타나요.","적도 주변의 열대와 맞은편 끝이에요."],"mis":"SO6-2-u1-X10"}'::jsonb),
('g6_2_soc_u1_L06_challenge#2','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',2,'mc','auto','냉대 기후에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"냉대 기후에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"주로 북반구에 나타난다","correct":true},{"t":"적도 바로 위에 띠를 이룬다","mis":"SO6-2-u1-X10"},{"t":"남반구에만 나타난다","mis":"SO6-2-u1-X10"},{"t":"매우 높은 산지에만 나타난다","mis":"SO6-2-u1-X14"}],"explanation":["기후 띠는 적도를 기준으로 남북이 비슷해요.","그런데 냉대 기후는 주로 북반구에 나타나요.","그래서 남쪽 띠는 대략적인 모습이에요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb),
('g6_2_soc_u1_L06_challenge#3','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','적도에서 북쪽으로 온대 기후 띠까지 쌓았어요. 그다음에 나타나는 기후는 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X14']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"적도에서 북쪽으로 온대 기후 띠까지 쌓았어요. 그다음에 나타나는 기후는 어느 것인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X10"},{"t":"열대 기후","mis":"SO6-2-u1-X10"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["차례는 열대 → 건조 → 온대 → 냉대 → 한대예요.","온대 다음은 냉대예요.","고산은 위도의 차례에 들지 않아요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb),
('g6_2_soc_u1_L06_challenge#4','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'ox','auto','「고산 기후」 카드가 위도의 차례에 들지 않은 까닭은 고산 기후가 위도가 아니라 해발 고도에 따라 나타나기 때문이에요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"ox","stem":"「고산 기후」 카드가 위도의 차례에 들지 않은 까닭은 고산 기후가 위도가 아니라 해발 고도에 따라 나타나기 때문이에요.","answer":"O","reason_options":[{"t":"매우 높은 산지에서는 위도와 상관없이 고산 기후가 나타나기 때문에","correct":true},{"t":"고산 기후는 극지방에서만 나타나기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["기후 띠는 위도의 차례예요.","고산 기후는 높이가 만든 기후예요.","그래서 높은 산지에 따로 놓여요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb),
('g6_2_soc_u1_L06_challenge#5','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'mc','auto','「어제 이 마을에는 비가 많이 왔다.」만 보고 이 마을의 기후를 정할 수 없는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"mc","stem":"「어제 이 마을에는 비가 많이 왔다.」만 보고 이 마을의 기후를 정할 수 없는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하루의 날씨만 보았을 뿐 여러 해의 평균 상태를 보지 않았기 때문에","correct":true},{"t":"비는 기후를 구분하는 기준이 아니기 때문에","mis":"SO6-2-u1-X10"},{"t":"어제는 공휴일이었기 때문에","mis":"SO6-2-u1-X08"},{"t":"마을에는 기후가 없기 때문에","mis":"SO6-2-u1-X08"}],"explanation":["기후는 여러 해에 걸친 평균 상태예요.","하루의 비는 날씨예요.","기후를 알려면 여러 해의 기온과 강수량을 봐요."]}'::jsonb),
('g6_2_soc_u1_L06_challenge#6','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'error','auto','기후를 구분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"기후를 구분하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「기후는 나라마다 하나씩 정해져서 나라 이름으로 구분해.」","correct":true,"mis_target":"SO6-2-u1-X10"},{"t":"이서 — 「기후는 주로 기온과 강수량을 기준으로 구분해.」","mis":"SO6-2-u1-X10"},{"t":"라온 — 「한 나라 안에서도 여러 기후가 나타날 수 있어.」","mis":"SO6-2-u1-X10"}],"explanation":["기후는 나라 이름으로 구분하지 않아요.","기온과 강수량이 기준이에요.","이서와 라온은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_L06_challenge#7','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',3,'match','auto','기후와 그 기후가 주로 나타나는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"match","stem":"기후와 그 기후가 주로 나타나는 곳을 알맞게 이으세요.","pairs":[{"l":"열대 기후","r":"적도 주변의 저위도"},{"l":"온대 기후","r":"중위도"},{"l":"한대 기후","r":"남극과 북극 주변의 고위도"},{"l":"고산 기후","r":"해발 고도가 매우 높은 곳"}],"mis":"SO6-2-u1-X10","explanation":["위도에 따라 기후가 달라요.","저위도 — 열대, 중위도 — 온대, 고위도 — 한대예요.","고산 기후는 높이가 정해요."]}'::jsonb),
('g6_2_soc_u1_L06_challenge#8','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'mc','auto','세계의 기후 분포를 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"mc","stem":"세계의 기후 분포를 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"주로 기온과 강수량으로 구분하며, 적도에서 극으로 열대·건조·온대·냉대·한대가 차례로 나타나고 매우 높은 산지에는 고산 기후가 나타난다","correct":true},{"t":"나라 이름으로 구분하며, 어느 위도에서나 같은 기후가 나타난다","mis":"SO6-2-u1-X10"},{"t":"기후는 위도와 상관없이 아무렇게나 흩어져 나타난다","mis":"SO6-2-u1-X10"},{"t":"적도에서 극으로 한대·냉대·온대·건조·열대가 차례로 나타난다","mis":"SO6-2-u1-X10"}],"explanation":["기준은 기온과 강수량이에요.","적도에서 극으로 열대부터 한대까지 차례가 있어요.","높은 산지는 고산 기후예요."],"asset":{"type":"passage","lines":["적도 → 북쪽으로 가면서 기후 띠를 쌓았다.","① 열대 기후 → ② 건조 기후 → ③ 온대 기후 → ④ 냉대 기후 → ⑤ 한대 기후","북쪽에 띠를 하나 쌓을 때마다 남쪽에도 같은 차례로 띠가 나타났다.","(냉대 기후는 주로 북반구에 나타난다.)","남은 카드 「고산 기후」는 위도의 차례가 아니라 매우 높은 산지에 놓였다."],"title":"적도에 비춰 보는 기후 띠"}}'::jsonb),
('g6_2_soc_u1_L06_challenge#9','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'essay','teacher','날씨와 기후의 차이를 예를 들어 쓰고, 세계의 기후가 지역마다 다르게 나타나는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"날씨와 기후의 차이를 예를 들어 쓰고, 세계의 기후가 지역마다 다르게 나타나는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「오늘은 맑고 덥다」처럼 짧은 기간의 대기 상태는 날씨이고, 「이 지역은 해마다 여름에 덥고 비가 많다」처럼 여러 해에 걸쳐 되풀이되는 평균 상태는 기후이다. 기후가 지역마다 다른 까닭은 위도가 달라 받는 햇볕의 양이 다르고, 해발 고도나 지형·위치가 다르기 때문이다.","scoring_points":["날씨와 기후의 차이를 예와 함께 썼는가","기후에 영향을 주는 요인을 두 가지 썼는가","위도만이 아니라 다른 요인도 들었는가"]},"explanation":["날씨 — 짧은 기간, 기후 — 여러 해의 평균이에요.","위도·위치·지형·해발 고도가 영향을 줘요.","둘 이상 들어 써요."]}'::jsonb),
('g6_2_soc_u1_L06_challenge#10','soc',6,2,'u1','L06','g6_2_soc_u1_L06_challenge','lesson_challenge','SO6-2-u1-C5',4,'essay','teacher','적도 주변에 있는 두 도시 가운데 한 곳은 일 년 내내 덥고, 다른 한 곳은 일 년 내내 서늘해요. 같은 적도 주변인데 기후가 다른 까닭을 쓰고, 각 도시의 기후 이름을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"적도 주변에 있는 두 도시 가운데 한 곳은 일 년 내내 덥고, 다른 한 곳은 일 년 내내 서늘해요. 같은 적도 주변인데 기후가 다른 까닭을 쓰고, 각 도시의 기후 이름을 쓰세요.","answer_guide":{"answer":"예: 두 도시는 위도가 비슷하지만 해발 고도가 다르다. 낮은 곳에 있는 도시는 일 년 내내 기온이 높은 열대 기후이고, 높은 산지에 있는 도시는 높이 올라갈수록 기온이 낮아져 일 년 내내 서늘한 고산 기후이다. 기후는 위도뿐 아니라 해발 고도에 따라서도 달라진다.","scoring_points":["해발 고도의 차이를 까닭으로 썼는가","두 도시의 기후 이름(열대·고산)을 바르게 썼는가","위도만으로 기후가 정해지지 않음이 드러나는가"]},"explanation":["위도가 같아도 높이가 다를 수 있어요.","높이 오르면 서늘해져요.","열대와 고산으로 갈려요."]}'::jsonb),
('g6_2_soc_u1_L07_basic#1','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',1,'mc','auto','열대 기후의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"mc","stem":"열대 기후의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"일 년 내내 기온이 높고 기온의 변화가 거의 없다","correct":true},{"t":"겨울이 여름보다 길고 몹시 춥다","mis":"SO6-2-u1-X11"},{"t":"강수량이 매우 적고 낮과 밤의 기온 차이가 크다","mis":"SO6-2-u1-X11"},{"t":"일 년 내내 눈과 얼음으로 덮여 있다","mis":"SO6-2-u1-X11"}],"explanation":["열대 기후는 적도 주변에 나타나요.","일 년 내내 덥고 기온 변화가 거의 없어요.","비가 적고 낮밤 차이가 큰 것은 건조 기후예요."]}'::jsonb),
('g6_2_soc_u1_L07_basic#2','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',1,'mc','auto','건조 기후의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"mc","stem":"건조 기후의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"강수량이 적고 낮과 밤의 기온 차이가 크다","correct":true},{"t":"일 년 내내 비가 많이 내린다","mis":"SO6-2-u1-X11"},{"t":"사계절의 변화가 뚜렷하다","mis":"SO6-2-u1-X13"},{"t":"일 년 내내 서늘하다","mis":"SO6-2-u1-X14"}],"explanation":["건조 기후는 비가 아주 적은 곳에 나타나요.","낮에는 뜨겁고 밤에는 쌀쌀해요.","사막이나 초원이 펼쳐져요."]}'::jsonb),
('g6_2_soc_u1_L07_basic#3','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',1,'sa','auto','나무와 풀을 태우고 남은 재를 거름 삼아 농사짓는 방식을 무엇이라고 하나요? 「○○ 농업」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C6","difficulty":1,"kind":"sa","stem":"나무와 풀을 태우고 남은 재를 거름 삼아 농사짓는 방식을 무엇이라고 하나요? 「○○ 농업」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["화전"],"explanation":["열대 기후 지역의 전통적인 농사 방식이에요.","카사바·얌·옥수수 등을 길렀어요.","재가 거름이 돼요."],"mis":"SO6-2-u1-X12"}'::jsonb),
('g6_2_soc_u1_L07_basic#4','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',1,'ox','auto','건조 기후 사막 지역의 사람들은 햇볕과 모래바람을 막으려고 온몸을 감싸는 옷을 입어요.',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C7","difficulty":1,"kind":"ox","stem":"건조 기후 사막 지역의 사람들은 햇볕과 모래바람을 막으려고 온몸을 감싸는 옷을 입어요.","answer":"O","reason_options":[{"t":"강한 햇볕과 모래바람으로부터 몸을 보호해야 하기 때문에","correct":true},{"t":"사막은 일 년 내내 추워서 두꺼운 옷이 필요하기 때문에","mis":"SO6-2-u1-X11"}],"mis":"SO6-2-u1-X11","explanation":["사막은 햇볕이 강해요.","모래바람도 불어요.","그래서 온몸을 감싸는 옷을 입어요."]}'::jsonb),
('g6_2_soc_u1_L07_basic#5','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'match','auto','기후 지역과 그곳의 집 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"match","stem":"기후 지역과 그곳의 집 모습을 알맞게 이으세요.","pairs":[{"l":"열대 기후 지역","r":"큰 창과 땅에서 띄운 바닥"},{"l":"건조 기후 사막 지역","r":"두꺼운 벽과 작은 창의 흙벽돌 집"},{"l":"건조 기후 초원 지역","r":"옮겨 다닐 수 있는 이동식 가옥"}],"mis":"SO6-2-u1-X12","explanation":["집은 기후에 맞추어 지어요.","열대 — 바람이 통하게, 사막 — 햇볕을 막게 해요.","초원 — 물과 풀을 찾아 옮겨 다녀요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb),
('g6_2_soc_u1_L07_basic#6','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역에서 오늘날 대규모로 재배하는 작물이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역에서 오늘날 대규모로 재배하는 작물이 아닌 것은 어느 것인가요?","options":[{"t":"올리브","correct":true},{"t":"천연고무","mis":"SO6-2-u1-X15"},{"t":"카카오","mis":"SO6-2-u1-X15"},{"t":"바나나","mis":"SO6-2-u1-X15"}],"explanation":["열대 기후 지역에서는 천연고무·카카오·바나나·커피를 대규모로 길러요.","올리브는 지중해 주변에서 많이 길러요.","기후마다 잘 자라는 작물이 달라요."]}'::jsonb),
('g6_2_soc_u1_L07_basic#7','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'mc','auto','열대 기후 지역의 집이 창을 크게 하고 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"열대 기후 지역의 집이 창을 크게 하고 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"덥고 습해서 바람이 잘 통하게 하고 땅의 습기와 물을 피하려고","correct":true},{"t":"모래바람이 집 안에 들어오게 하려고","mis":"SO6-2-u1-X12"},{"t":"추운 겨울에 햇볕을 많이 받으려고","mis":"SO6-2-u1-X12"},{"t":"물과 풀을 찾아 옮겨 다니려고","mis":"SO6-2-u1-X12"}],"explanation":["열대 기후는 덥고 비가 많아요.","큰 창으로 바람이 통하게 해요.","바닥을 띄워 습기와 물을 피해요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb),
('g6_2_soc_u1_L07_basic#8','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',2,'mc','auto','건조 기후의 초원 지역 사람들이 이동식 가옥에서 사는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X02','SO6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"mc","stem":"건조 기후의 초원 지역 사람들이 이동식 가옥에서 사는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물과 풀을 찾아 가축과 함께 옮겨 다니기 때문에","correct":true},{"t":"비가 너무 많이 와서 집이 잠기기 때문에","mis":"SO6-2-u1-X11"},{"t":"땅속에 구리가 많기 때문에","mis":"SO6-2-u1-X02"},{"t":"바닷물이 자주 들어오기 때문에","mis":"SO6-2-u1-X03"}],"explanation":["초원은 비가 조금 와서 풀이 자라요.","사람들은 가축을 기르며 물과 풀을 찾아 옮겨 다녀요.","그래서 옮기기 쉬운 집에서 살아요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb),
('g6_2_soc_u1_L07_basic#9','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C6',2,'ox','auto','열대 기후 지역에는 비가 일 년 내내 많이 와 열대 우림을 이루는 곳도 있고, 건기와 우기가 번갈아 와 초원이 펼쳐진 곳도 있어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"ox","stem":"열대 기후 지역에는 비가 일 년 내내 많이 와 열대 우림을 이루는 곳도 있고, 건기와 우기가 번갈아 와 초원이 펼쳐진 곳도 있어요.","answer":"O","reason_options":[{"t":"같은 열대 기후라도 비가 오는 모양에 따라 경관이 다르기 때문에","correct":true},{"t":"열대 기후 지역은 모두 사막이기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["우기는 비가 많은 때, 건기는 비가 적은 때예요.","비가 늘 많으면 열대 우림이 돼요.","건기·우기가 번갈아 오면 초원이 펼쳐져요."]}'::jsonb),
('g6_2_soc_u1_L07_basic#10','soc',6,2,'u1','L07','g6_2_soc_u1_L07_basic','lesson_basic','SO6-2-u1-C7',3,'error','auto','두 기후 지역의 집을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"error","stem":"두 기후 지역의 집을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「사막 지역의 집도 바람이 잘 통하게 창을 크게 만들어.」","correct":true,"mis_target":"SO6-2-u1-X12"},{"t":"승우 — 「사막 지역의 집은 햇볕과 모래바람을 막으려고 창이 작아.」","mis":"SO6-2-u1-X12"},{"t":"보람 — 「열대 지역의 집은 바닥을 땅에서 띄우기도 해.」","mis":"SO6-2-u1-X12"}],"explanation":["사막은 햇볕과 모래바람을 막아야 해요.","그래서 벽이 두껍고 창이 작아요.","승우와 보람은 바르게 말했어요."],"asset":{"type":"passage","lines":["열대 기후 지역의 집 — 바람이 잘 통하는 큰 창, 기둥을 세워 땅에서 띄운 바닥, 얇은 옷","건조 기후 사막 지역의 집 — 햇볕과 모래바람을 막는 두꺼운 벽과 작은 창, 온몸을 감싸는 옷","건조 기후 초원 지역 — 물과 풀을 찾아 옮겨 다니며 이동식 가옥에서 생활"],"title":"기후에 맞춘 두 기후 지역의 집"}}'::jsonb),
