('g6_2_soc_u1_L09_challenge#4','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'error','auto','한대·고산 기후 지역의 생활을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"error","stem":"한대·고산 기후 지역의 생활을 짝지어 말했어요. 잘못 짝지은 친구는 누구인가요?","options":[{"t":"소율 — 「고산 기후 — 순록 유목과 오로라 관광」","correct":true,"mis_target":"SO6-2-u1-X14"},{"t":"건우 — 「한대 기후 — 사냥으로 얻은 생선과 고기」","mis":"SO6-2-u1-X14"},{"t":"지아 — 「고산 기후 — 알파카와 라마 기르기」","mis":"SO6-2-u1-X14"}],"explanation":["순록 유목과 오로라 관광은 한대 기후 지역이에요.","고산 기후는 알파카·라마, 감자·옥수수예요.","건우와 지아는 바르게 짝지었어요."]}'::jsonb),
('g6_2_soc_u1_L09_challenge#5','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'ox','auto','고산 기후는 극지방처럼 일 년 내내 눈과 얼음으로 덮여 있는 기후예요.',ARRAY['SO6-2-u1-X14']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"ox","stem":"고산 기후는 극지방처럼 일 년 내내 눈과 얼음으로 덮여 있는 기후예요.","answer":"X","reason_options":[{"t":"적도 주변의 일부 고산 기후 지역은 일 년 내내 서늘해 사람이 많이 모여 살기 때문에","correct":true},{"t":"높은 곳은 모두 극지방과 같기 때문에","mis":"SO6-2-u1-X14"}],"mis":"SO6-2-u1-X14","explanation":["눈과 얼음에 덮인 곳이 많은 것은 한대 기후예요.","고산 기후는 서늘한 날씨가 이어지는 곳이 있어요.","두 기후를 헷갈리지 않아요."]}'::jsonb),
('g6_2_soc_u1_L09_challenge#6','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'mc','auto','키토(에콰도르)는 적도 가까이 있는데도 일 년 내내 서늘해요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X09','SO6-2-u1-X08']::text[],false,'{"seq":6,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"키토(에콰도르)는 적도 가까이 있는데도 일 년 내내 서늘해요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"해발 고도가 높은 곳에 있기 때문에","correct":true},{"t":"남극과 가까이 있기 때문에","mis":"SO6-2-u1-X09"},{"t":"바닷물이 차갑기 때문에","mis":"SO6-2-u1-X09"},{"t":"하루 내내 비가 오기 때문에","mis":"SO6-2-u1-X08"}],"explanation":["적도 주변의 낮은 곳은 일 년 내내 더워요.","키토는 높은 산지에 있어요.","그래서 고산 기후가 나타나요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb),
('g6_2_soc_u1_L09_challenge#7','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',3,'match','auto','기후와 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"match","stem":"기후와 그 특징을 알맞게 이으세요.","pairs":[{"l":"한대 기후","r":"겨울이 길고 기온이 매우 낮다"},{"l":"고산 기후","r":"일 년 내내 서늘하고 낮과 밤의 기온 차이가 크다"},{"l":"냉대 기후","r":"사계절이 있지만 겨울이 여름보다 길고 몹시 춥다"}],"mis":"SO6-2-u1-X14","explanation":["세 기후 모두 추운 쪽이에요.","한대는 매우 춥고, 고산은 서늘해요.","냉대는 사계절이 있어요."]}'::jsonb),
('g6_2_soc_u1_L09_challenge#8','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'mc','auto','한대 기후 지역에서 최근 생활 모습이 바뀌고 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X15','SO6-2-u1-X11']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"mc","stem":"한대 기후 지역에서 최근 생활 모습이 바뀌고 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지하자원 개발·극지방 기후 연구·오로라와 빙하 관광처럼 새로운 일이 늘고 있기 때문에","correct":true},{"t":"한대 기후가 갑자기 열대 기후로 바뀌었기 때문에","mis":"SO6-2-u1-X10"},{"t":"사람들이 모두 벼농사를 짓기 시작했기 때문에","mis":"SO6-2-u1-X15"},{"t":"한대 기후 지역에 사막이 생겼기 때문에","mis":"SO6-2-u1-X11"}],"explanation":["예전에는 사냥과 순록 유목이 중심이었어요.","최근에는 자원 개발·연구·관광이 활발해요.","사람들은 기후를 극복하며 새 일을 찾아요."]}'::jsonb),
('g6_2_soc_u1_L09_challenge#9','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'essay','teacher','한대 기후와 고산 기후는 둘 다 추운 쪽의 기후예요. 두 기후가 나타나는 곳과 생활 모습을 하나씩 견주어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"한대 기후와 고산 기후는 둘 다 추운 쪽의 기후예요. 두 기후가 나타나는 곳과 생활 모습을 하나씩 견주어 쓰세요.","answer_guide":{"answer":"예: 한대 기후는 남극과 북극 주변의 고위도 지역에 나타나며, 사람들은 사냥해 얻은 생선과 고기를 먹고 이끼가 자라는 곳에서 순록을 기른다. 고산 기후는 해발 고도가 높은 곳에 나타나며, 사람들은 감자와 옥수수를 기르고 알파카와 라마를 키우며 챙 넓은 모자와 여러 겹의 옷으로 기후에 적응한다.","scoring_points":["두 기후가 나타나는 곳을 바르게 썼는가","두 기후의 생활 모습을 하나씩 바르게 썼는가","고위도와 고산의 차이가 드러나는가"]},"explanation":["한대 — 고위도예요.","고산 — 높은 곳이에요.","생활 모습도 달라요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb),
('g6_2_soc_u1_L09_challenge#10','soc',6,2,'u1','L09','g6_2_soc_u1_L09_challenge','lesson_challenge','SO6-2-u1-C9',4,'essay','teacher','고산 기후 지역 사람들이 기후에 적응하는 옷차림을 두 가지 쓰고, 각각 어떤 기후 특징에 맞춘 것인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"고산 기후 지역 사람들이 기후에 적응하는 옷차림을 두 가지 쓰고, 각각 어떤 기후 특징에 맞춘 것인지 쓰세요.","answer_guide":{"answer":"예: 챙이 넓고 둥근 모자를 쓰는데, 높은 곳이라 햇빛이 강하기 때문이다. 옷을 여러 겹 입고 망토를 두르는데, 낮과 밤의 기온 차이가 커서 입고 벗으며 맞추기 위해서이다.","scoring_points":["옷차림을 두 가지 썼는가","각각 맞춘 기후 특징을 썼는가","기후에 적응한다는 점이 드러나는가"]},"explanation":["강한 햇빛 → 챙 넓은 모자예요.","큰 일교차 → 여러 겹 옷과 망토예요.","기후에 맞춘 생활이에요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#1','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'mc','auto','기후와 사람들의 생활에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X02','SO6-2-u1-X15']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"기후와 사람들의 생활에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"사람들은 기후에 적응하고 이를 극복하면서 다양한 모습으로 살아간다","correct":true},{"t":"기후는 사람들의 생활과 관계가 없다","mis":"SO6-2-u1-X02"},{"t":"같은 기후 지역의 생활은 모두 똑같다","mis":"SO6-2-u1-X15"},{"t":"사람들은 기후를 전혀 바꾸거나 이겨 내지 못한다","mis":"SO6-2-u1-X02"}],"explanation":["기후는 생활에 큰 영향을 줘요.","사람들은 기후에 맞추어 살아요.","기후를 극복하는 방법도 찾아요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#2','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'mc','auto','기후와 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"기후와 생활 모습을 조사하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 인터넷으로 조사하기 → 디지털 영상 지도에 표시하기 → 공유하기","correct":true},{"t":"공유하기 → 주제 정하기 → 지도에 표시하기 → 조사하기","mis":"SO6-2-u1-X17"},{"t":"지도에 표시하기 → 공유하기 → 조사하기 → 주제 정하기","mis":"SO6-2-u1-X17"},{"t":"조사하기 → 공유하기 → 주제 정하기 → 지도에 표시하기","mis":"SO6-2-u1-X17"}],"explanation":["먼저 주제를 정해요.","조사한 것을 지도에 표시해요.","그다음 친구들과 공유해요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#3','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'ox','auto','상품 판매 계획을 세울 때는 판매할 나라의 지형과 기후를 조사해야 해요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"ox","stem":"상품 판매 계획을 세울 때는 판매할 나라의 지형과 기후를 조사해야 해요.","answer":"O","reason_options":[{"t":"그곳 사람들에게 필요한 상품은 그곳의 자연환경에 따라 달라지기 때문에","correct":true},{"t":"상품은 어느 나라에서나 똑같이 쓰이기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["자연환경은 생활의 불편과 필요를 만들어요.","지형과 기후를 조사해요.","그 특징을 상품에 담아요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#4','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',1,'sa','auto','자연환경을 고려한 상품 판매 계획에서 가장 먼저 하는 일은 판매할 무엇을 정하는 것인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"sa","stem":"자연환경을 고려한 상품 판매 계획에서 가장 먼저 하는 일은 판매할 무엇을 정하는 것인가요? 두 글자로 쓰세요.","answer":["나라"],"explanation":["먼저 판매할 나라를 정해요.","그다음 그 나라의 지형과 기후를 조사해요.","아이디어를 이야기하고 계획을 세워요."],"mis":"SO6-2-u1-X17"}'::jsonb),
('g6_2_soc_u1_L10_basic#5','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','노르웨이의 냉대 기후 지역에 팔 방한용 안전 신발에 스파이크를 단 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"노르웨이의 냉대 기후 지역에 팔 방한용 안전 신발에 스파이크를 단 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"겨울이 길고 눈과 얼음이 많아 미끄러지지 않게 하려고","correct":true},{"t":"일 년 내내 덥고 비가 많아서","mis":"SO6-2-u1-X11"},{"t":"모래바람이 심해서","mis":"SO6-2-u1-X11"},{"t":"바닷가 모래사장에서 걷기 좋게 하려고","mis":"SO6-2-u1-X16"}],"explanation":["냉대 기후는 겨울이 길고 몹시 추워요.","눈과 얼음 위에서 미끄러지기 쉬워요.","스파이크가 그 불편을 덜어 줘요."],"asset":{"type":"passage","lines":["판매할 나라 — 노르웨이","기후의 특징 — 겨울이 여름보다 길고 몹시 추우며 눈이 많이 온다","판매 동기 — 겨울에 밖에서 이동하기가 불편하다","상품 — 방한용 안전 신발","상품 특징 — 바닥 스파이크 · 스키 부착 · 열선"],"title":"자연환경을 고려한 상품 판매 계획서(예)"}}'::jsonb),
('g6_2_soc_u1_L10_basic#6','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'match','auto','자연환경의 특징과 그곳에 맞는 상품 아이디어를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"match","stem":"자연환경의 특징과 그곳에 맞는 상품 아이디어를 알맞게 이으세요.","pairs":[{"l":"브라질의 열대 우림","r":"해충 퇴치기"},{"l":"콩고강","r":"튼튼한 어망"},{"l":"네팔 히말라야산맥","r":"만능 등산 장비"},{"l":"노르웨이의 냉대 기후","r":"방한용 안전 신발"}],"mis":"SO6-2-u1-X16","explanation":["상품은 그곳의 자연환경에 맞춰요.","열대 우림 — 벌레, 강 — 고기잡이예요.","높은 산 — 등산, 추위 — 방한이에요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#7','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','자연환경을 고려한 상품 판매 계획의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":7,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"나라 정하기 → 지형과 기후 조사하기 → 아이디어 이야기하기 → 판매 계획 세우기 → 글과 그림으로 나타내기","correct":true},{"t":"글과 그림으로 나타내기 → 나라 정하기 → 판매 계획 세우기 → 조사하기","mis":"SO6-2-u1-X17"},{"t":"판매 계획 세우기 → 조사하기 → 나라 정하기 → 아이디어 이야기하기","mis":"SO6-2-u1-X17"},{"t":"아이디어 이야기하기 → 글과 그림 → 나라 정하기 → 조사하기","mis":"SO6-2-u1-X17"}],"explanation":["나라를 먼저 정해요.","지형과 기후를 조사하고 아이디어를 나눠요.","계획을 세워 글과 그림으로 나타내요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#8','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'ox','auto','같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타날 수 있어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타날 수 있어요.","answer":"O","reason_options":[{"t":"같은 온대 기후에서도 밀·올리브·벼처럼 지역마다 생활이 다르기 때문에","correct":true},{"t":"같은 기후면 생활도 꼭 같기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["같은 기후 칸에도 여러 핀이 설 수 있어요.","온대 기후에서도 지역마다 농업이 달라요.","생활은 여러 가지예요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#9','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',2,'mc','auto','상품 아이디어를 고를 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"상품 아이디어를 고를 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"아이디어를 실제로 만들 수 있을지(실현 가능성)","correct":true},{"t":"이름이 가장 긴 상품인지","mis":"SO6-2-u1-X16"},{"t":"어느 나라에서나 똑같이 쓸 수 있는지","mis":"SO6-2-u1-X16"},{"t":"그림을 그리기 쉬운지","mis":"SO6-2-u1-X16"}],"explanation":["좋은 아이디어도 만들 수 있어야 해요.","실현 가능성을 함께 따져요.","자연환경에 맞는지도 봐요."]}'::jsonb),
('g6_2_soc_u1_L10_basic#10','soc',6,2,'u1','L10','g6_2_soc_u1_L10_basic','lesson_basic','SO6-2-u1-C10',3,'error','auto','상품 판매 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"error","stem":"상품 판매 계획을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한 가지 상품을 만들면 세계 어느 곳에서나 똑같이 잘 팔릴 거야.」","correct":true,"mis_target":"SO6-2-u1-X16"},{"t":"주원 — 「판매할 곳의 지형이나 기후에 맞춘 기능을 넣어야 해.」","mis":"SO6-2-u1-X16"},{"t":"하린 — 「곳이 바뀌면 맞는 기능도 바뀌어.」","mis":"SO6-2-u1-X16"}],"explanation":["자연환경이 다르면 필요한 것도 달라요.","곳마다 맞는 기능이 있어요.","주원과 하린은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_L10_challenge#1','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',2,'sa','auto','사람들이 기후에 맞추어 살아가는 것을 「적응」이라고 해요. 기후의 어려움을 이겨 내는 것은 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"sa","stem":"사람들이 기후에 맞추어 살아가는 것을 「적응」이라고 해요. 기후의 어려움을 이겨 내는 것은 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["극복"],"explanation":["사람들은 기후에 적응해요.","기후의 어려움을 극복하기도 해요.","두 가지가 함께 생활을 만들어요."],"mis":"SO6-2-u1-X02"}'::jsonb),
('g6_2_soc_u1_L10_challenge#2','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',2,'mc','auto','네팔 히말라야산맥을 오르는 셰르파를 위한 상품 아이디어로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"네팔 히말라야산맥을 오르는 셰르파를 위한 상품 아이디어로 알맞은 것은 어느 것인가요?","options":[{"t":"만능 등산 장비","correct":true},{"t":"해충 퇴치기","mis":"SO6-2-u1-X16"},{"t":"수상 시장용 배","mis":"SO6-2-u1-X16"},{"t":"사막용 물주머니","mis":"SO6-2-u1-X16"}],"explanation":["히말라야산맥은 높고 험한 산지예요.","셰르파는 산을 오르는 사람들이에요.","그래서 등산 장비가 필요해요."]}'::jsonb),
('g6_2_soc_u1_L10_challenge#3','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'mc','auto','추위가 심한 냉대 기후 지역과 한대 기후 지역에 같은 기능(열선)을 넣은 상품을 팔 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X16','SO6-2-u1-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"추위가 심한 냉대 기후 지역과 한대 기후 지역에 같은 기능(열선)을 넣은 상품을 팔 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 곳 모두 추위라는 같은 특징이 있기 때문에","correct":true},{"t":"두 곳 모두 열대 기후이기 때문에","mis":"SO6-2-u1-X10"},{"t":"상품은 어디서나 똑같이 쓰이기 때문에","mis":"SO6-2-u1-X16"},{"t":"두 곳 모두 비가 거의 오지 않기 때문에","mis":"SO6-2-u1-X11"}],"explanation":["곳이 바뀌면 맞는 기능도 바뀌어요.","하지만 같은 특징이 있는 곳에는 같은 기능이 쓰여요.","추위 → 열선이에요."]}'::jsonb),
('g6_2_soc_u1_L10_challenge#4','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'error','auto','기후와 생활 조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X15','SO6-2-u1-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"error","stem":"기후와 생활 조사를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「한 나라의 생활 모습을 조사하면 그 기후 전체의 생활을 다 안 거야.」","correct":true,"mis_target":"SO6-2-u1-X15"},{"t":"채원 — 「같은 온대 기후 칸에도 여러 생활 모습이 있었어.」","mis":"SO6-2-u1-X15"},{"t":"지민 — 「조사한 곳을 디지털 영상 지도에 표시해 공유하자.」","mis":"SO6-2-u1-X17"}],"explanation":["한 곳의 모습이 그 기후 전체는 아니에요.","같은 기후에도 생활은 여러 가지예요.","채원과 지민은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_L10_challenge#5','soc',6,2,'u1','L10','g6_2_soc_u1_L10_challenge','lesson_challenge','SO6-2-u1-C10',3,'ox','auto','브라질의 열대 우림 지역에 해충 퇴치기를 파는 계획은 그곳의 자연환경을 고려한 계획이에요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"ox","stem":"브라질의 열대 우림 지역에 해충 퇴치기를 파는 계획은 그곳의 자연환경을 고려한 계획이에요.","answer":"O","reason_options":[{"t":"일 년 내내 덥고 비가 많아 벌레가 많은 열대 우림의 특징에 맞추었기 때문에","correct":true},{"t":"해충 퇴치기는 어느 나라에서나 똑같이 필요하기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["브라질은 열대 기후가 나타나요.","아마존강 주변에 열대 우림이 넓어요.","덥고 습해 벌레가 많아요."]}'::jsonb),
