('g6_2_soc_u1_review_a#8','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',1,'mc','auto','자연환경을 고려한 상품 판매 계획을 세울 때 그 나라에서 조사할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":8,"concept":"SO6-2-u1-C10","difficulty":1,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획을 세울 때 그 나라에서 조사할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"지형과 기후","correct":true},{"t":"그 나라 국기의 모양","mis":"SO6-2-u1-X16"},{"t":"그 나라 사람들의 이름","mis":"SO6-2-u1-X16"},{"t":"그 나라의 인기 노래","mis":"SO6-2-u1-X16"}],"explanation":["자연환경은 지형과 기후예요.","사람들의 불편과 필요가 여기서 나와요.","그 특징을 상품에 담아요."]}'::jsonb),
('g6_2_soc_u1_review_a#9','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',2,'mc','auto','여행 엽서 ㉮의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X11','SO6-2-u1-X13','SO6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉮의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"열대 기후","correct":true},{"t":"건조 기후","mis":"SO6-2-u1-X11"},{"t":"냉대 기후","mis":"SO6-2-u1-X13"},{"t":"고산 기후","mis":"SO6-2-u1-X14"}],"explanation":["일 년 내내 덥고 비가 자주 와요.","바닥을 띄운 집과 카카오 농장이 있어요.","열대 기후의 생활이에요."],"asset":{"type":"passage","lines":["이곳은 일 년 내내 덥고 거의 날마다 소나기가 와.","키 큰 나무가 빽빽한 숲 사이로 바닥을 땅에서 띄운 집이 보여.","마을 사람들은 큰 농장에서 카카오를 기른대."],"title":"여행 엽서 ㉮"}}'::jsonb),
('g6_2_soc_u1_review_a#10','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',2,'mc','auto','여행 엽서 ㉱에서 사람들이 하고 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉱에서 사람들이 하고 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌을 이용해 소금을 만드는 일","correct":true},{"t":"배가 드나드는 항구를 짓는 일","mis":"SO6-2-u1-X06"},{"t":"구리를 캐는 일","mis":"SO6-2-u1-X03"},{"t":"양을 기르는 일","mis":"SO6-2-u1-X03"}],"explanation":["바다와 땅이 만나는 해안이에요.","넓은 갯벌에 바닷물을 가두어 말려요.","하얀 알갱이는 소금이에요."],"asset":{"type":"passage","lines":["바다와 땅이 만나는 곳이야. 물이 빠지면 넓은 갯벌이 드러나.","네모난 칸마다 바닷물을 가두어 햇볕에 말려.","하얀 알갱이를 긁어모으는 사람들이 보여."],"title":"여행 엽서 ㉱"}}'::jsonb),
('g6_2_soc_u1_review_a#11','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',2,'ox','auto','관광객이 늘어난 해안에서는 일자리와 소득뿐 아니라 쓰레기와 오염도 함께 늘 수 있어요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"ox","stem":"관광객이 늘어난 해안에서는 일자리와 소득뿐 아니라 쓰레기와 오염도 함께 늘 수 있어요.","answer":"O","reason_options":[{"t":"관광에는 긍정적인 영향과 부정적인 영향이 함께 있기 때문에","correct":true},{"t":"관광은 좋은 점만 가져오기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광은 일자리와 소득을 늘려요.","쓰레기와 오염도 늘어요.","두 쪽을 함께 봐요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_review_a#12','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',2,'mc','auto','같은 적도 주변인데도 한 곳은 덥고 다른 곳은 서늘한 까닭이 되는 요인은 어느 것인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X08']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"같은 적도 주변인데도 한 곳은 덥고 다른 곳은 서늘한 까닭이 되는 요인은 어느 것인가요?","options":[{"t":"해발 고도","correct":true},{"t":"나라 이름","mis":"SO6-2-u1-X10"},{"t":"인구","mis":"SO6-2-u1-X10"},{"t":"요일","mis":"SO6-2-u1-X08"}],"explanation":["위도가 같아도 높이가 다를 수 있어요.","높이 오르면 서늘해져요.","해발 고도도 기후에 영향을 줘요."]}'::jsonb),
('g6_2_soc_u1_review_a#13','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C6',2,'match','auto','기후와 그곳의 집이나 옷을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"match","stem":"기후와 그곳의 집이나 옷을 알맞게 이으세요.","pairs":[{"l":"열대 기후","r":"바닥을 띄운 집과 얇은 옷"},{"l":"건조 기후 사막","r":"두꺼운 벽의 흙벽돌 집과 온몸을 감싸는 옷"},{"l":"고산 기후","r":"챙 넓은 모자와 여러 겹의 옷"}],"mis":"SO6-2-u1-X12","explanation":["집과 옷은 기후에 맞춰요.","열대 — 바람, 사막 — 햇볕과 모래를 생각해요.","고산 — 강한 햇빛과 큰 일교차예요."]}'::jsonb),
('g6_2_soc_u1_review_a#14','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C8',2,'ox','auto','같은 온대 기후 지역이면 어디서나 벼농사를 지어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"ox","stem":"같은 온대 기후 지역이면 어디서나 벼농사를 지어요.","answer":"X","reason_options":[{"t":"서부 유럽은 밀·낙농업, 지중해 주변은 올리브·포도처럼 지역마다 농업이 다르기 때문에","correct":true},{"t":"온대 기후는 벼만 자라는 기후이기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["같은 온대 기후도 지역마다 달라요.","비가 오는 모양과 기온이 조금씩 달라요.","그래서 농업도 여러 가지예요."]}'::jsonb),
('g6_2_soc_u1_review_a#15','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C2',2,'mc','auto','산지 가운데 넓고 평평하며 풀이 잘 자라는 고원에서 사람들이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X04','SO6-2-u1-X03']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"mc","stem":"산지 가운데 넓고 평평하며 풀이 잘 자라는 고원에서 사람들이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"양 같은 가축을 기른다","correct":true},{"t":"계단식 논을 만든다","mis":"SO6-2-u1-X04"},{"t":"수상 시장을 연다","mis":"SO6-2-u1-X03"},{"t":"염전을 만든다","mis":"SO6-2-u1-X03"}],"explanation":["고원은 높지만 평평해요.","풀이 잘 자라 가축을 길러요.","파미르고원이 예예요."]}'::jsonb),
('g6_2_soc_u1_review_a#16','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',2,'mc','auto','일 년 내내 덥고 비가 많아 벌레가 많은 열대 우림 지역에 알맞은 상품은 어느 것인가요?',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"mc","stem":"일 년 내내 덥고 비가 많아 벌레가 많은 열대 우림 지역에 알맞은 상품은 어느 것인가요?","options":[{"t":"해충 퇴치기","correct":true},{"t":"스파이크가 달린 방한 신발","mis":"SO6-2-u1-X16"},{"t":"눈썰매","mis":"SO6-2-u1-X16"},{"t":"모래바람 가리개","mis":"SO6-2-u1-X16"}],"explanation":["열대 우림은 덥고 습해요.","벌레가 많아요.","해충 퇴치기가 쓸모 있어요."]}'::jsonb),
('g6_2_soc_u1_review_a#17','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C3',3,'error','auto','하천 지형의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X05']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C3","difficulty":3,"kind":"error","stem":"하천 지형의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「강가의 넓은 평야는 바닷물이 들어와서 생긴 거야.」","correct":true,"mis_target":"SO6-2-u1-X05"},{"t":"지호 — 「강물이 날라 온 흙이 쌓여 평야가 생겨.」","mis":"SO6-2-u1-X05"},{"t":"나은 — 「강은 배가 물건을 실어 나르는 길이 되기도 해.」","mis":"SO6-2-u1-X05"}],"explanation":["평야는 강물이 날라 온 흙이 쌓여 생겨요.","바닷물이 들어오는 것은 피오르 같은 해안이에요.","지호와 나은은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_review_a#18','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',3,'error','auto','적도에서 극으로 가는 기후의 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X10','SO6-2-u1-X09']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C5","difficulty":3,"kind":"error","stem":"적도에서 극으로 가는 기후의 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「적도에서 극으로 가면 한대·냉대·온대·건조·열대 차례로 나타나.」","correct":true,"mis_target":"SO6-2-u1-X10"},{"t":"이서 — 「적도에서 극으로 가면 열대부터 한대까지 차례로 나타나.」","mis":"SO6-2-u1-X10"},{"t":"라온 — 「매우 높은 산지에는 고산 기후가 나타나.」","mis":"SO6-2-u1-X09"}],"explanation":["적도는 열대에서 시작해요.","열대 → 건조 → 온대 → 냉대 → 한대예요.","도하는 차례를 거꾸로 말했어요."]}'::jsonb),
('g6_2_soc_u1_review_a#19','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',3,'mc','auto','여행 엽서 ㉯의 곳을 「한대 기후가 아니라 고산 기후」라고 판단할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X08']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"여행 엽서 ㉯의 곳을 「한대 기후가 아니라 고산 기후」라고 판단할 수 있는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「적도 가까운 나라인데 높은 산 위라 서늘해」","correct":true},{"t":"「사람들은 망토를 둘렀어」","mis":"SO6-2-u1-X14"},{"t":"「알파카가 풀을 뜯고 있어」","mis":"SO6-2-u1-X14"},{"t":"「한낮」이라는 말이 있어서","mis":"SO6-2-u1-X08"}],"explanation":["추운 기후로 가는 길은 둘이에요.","적도 가까운 곳의 높은 산이면 고산 기후예요.","망토·알파카만으로는 위도를 알 수 없어요."],"asset":{"type":"passage","lines":["적도 가까운 나라인데 높은 산 위라 한낮에도 서늘해.","사람들은 챙 넓은 둥근 모자를 쓰고 망토를 둘렀어.","언덕에서 털이 복슬복슬한 알파카가 풀을 뜯고 있어."],"title":"여행 엽서 ㉯"}}'::jsonb),
('g6_2_soc_u1_review_a#20','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C9',3,'mc','auto','한대 기후와 고산 기후를 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X09','SO6-2-u1-X11']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C9","difficulty":3,"kind":"mc","stem":"한대 기후와 고산 기후를 바르게 견준 것은 어느 것인가요?","options":[{"t":"한대는 극지방 주변의 고위도에, 고산은 해발 고도가 높은 곳에 나타난다","correct":true},{"t":"한대는 높은 산에, 고산은 극지방에 나타난다","mis":"SO6-2-u1-X14"},{"t":"둘 다 적도 주변의 낮은 곳에 나타난다","mis":"SO6-2-u1-X09"},{"t":"둘 다 일 년 내내 덥다","mis":"SO6-2-u1-X11"}],"explanation":["추운 기후로 가는 길은 둘이에요.","고위도로 가면 한대예요.","높이 오르면 고산이에요."]}'::jsonb),
('g6_2_soc_u1_review_a#21','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C10',3,'mc','auto','자연환경을 고려한 상품 판매 계획에서 「아이디어 이야기하기」 바로 앞에 할 일은 어느 것인가요?',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"mc","stem":"자연환경을 고려한 상품 판매 계획에서 「아이디어 이야기하기」 바로 앞에 할 일은 어느 것인가요?","options":[{"t":"지형과 기후 조사하기","correct":true},{"t":"글과 그림으로 나타내기","mis":"SO6-2-u1-X17"},{"t":"판매 계획 세우기","mis":"SO6-2-u1-X17"},{"t":"발표하기","mis":"SO6-2-u1-X17"}],"explanation":["나라를 정하고 지형과 기후를 조사해요.","그다음 아이디어를 이야기해요.","계획을 세워 글과 그림으로 나타내요."]}'::jsonb),
('g6_2_soc_u1_review_a#22','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',3,'mc','auto','관광이 늘어난 섬이 「섬을 한동안 쉬게 하기로」 할 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07','SO6-2-u1-X02']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"mc","stem":"관광이 늘어난 섬이 「섬을 한동안 쉬게 하기로」 할 때 함께 생각해야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"오염이 줄어드는 대신 섬 사람들의 일자리와 소득도 줄어든다는 점","correct":true},{"t":"섬을 쉬게 하면 좋은 점만 생긴다는 점","mis":"SO6-2-u1-X07"},{"t":"관광은 섬과 아무 관계가 없다는 점","mis":"SO6-2-u1-X02"},{"t":"쉬게 하면 관광객이 더 늘어난다는 점","mis":"SO6-2-u1-X07"}],"explanation":["관광의 영향은 함께 움직여요.","줄이면 오염도 일자리도 줄어요.","두 쪽을 함께 따져요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_review_a#23','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',4,'mc','auto','여행 엽서 ㉮·㉯·㉰·㉵의 곳을 기후 이름과 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X13']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"mc","stem":"여행 엽서 ㉮·㉯·㉰·㉵의 곳을 기후 이름과 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉮ 열대 · ㉯ 고산 · ㉰ 냉대 · ㉵ 한대","correct":true},{"t":"㉮ 건조 · ㉯ 한대 · ㉰ 온대 · ㉵ 고산","mis":"SO6-2-u1-X14"},{"t":"㉮ 열대 · ㉯ 한대 · ㉰ 냉대 · ㉵ 고산","mis":"SO6-2-u1-X14"},{"t":"㉮ 온대 · ㉯ 고산 · ㉰ 한대 · ㉵ 냉대","mis":"SO6-2-u1-X13"}],"explanation":["㉮ — 늘 덥고 비, 카카오 → 열대예요.","㉯ — 적도 가까운 높은 산 → 고산, ㉰ — 긴 겨울·침엽수 → 냉대예요.","㉵ — 오로라·순록 → 한대예요."]}'::jsonb),
('g6_2_soc_u1_review_a#24','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C5',4,'essay','teacher','여행 엽서 ㉯의 곳은 적도 가까이 있는데도 서늘해요. 그 까닭을 쓰고, 이곳 사람들이 기후에 적응하는 생활 모습을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C5","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉯의 곳은 적도 가까이 있는데도 서늘해요. 그 까닭을 쓰고, 이곳 사람들이 기후에 적응하는 생활 모습을 두 가지 쓰세요.","answer_guide":{"answer":"예: 위도는 적도 가까이에 있지만 해발 고도가 높은 산 위라서 높이 올라갈수록 기온이 낮아져 일 년 내내 서늘한 고산 기후가 나타난다. 이곳 사람들은 강한 햇빛을 막으려고 챙 넓은 둥근 모자를 쓰고, 낮과 밤의 기온 차이에 맞추려고 옷을 여러 겹 입고 망토를 두른다. 또 알파카와 라마를 기르고 감자와 옥수수를 재배한다.","scoring_points":["해발 고도가 높아 서늘하다는 까닭을 썼는가","고산 기후임을 밝혔는가","기후에 적응하는 생활 모습을 두 가지 썼는가"]},"explanation":["위도만으로 기후가 정해지지 않아요.","높이가 기후를 바꿔요.","모자·옷·알파카가 적응의 모습이에요."],"asset":{"type":"passage","lines":["적도 가까운 나라인데 높은 산 위라 한낮에도 서늘해.","사람들은 챙 넓은 둥근 모자를 쓰고 망토를 둘렀어.","언덕에서 털이 복슬복슬한 알파카가 풀을 뜯고 있어."],"title":"여행 엽서 ㉯"}}'::jsonb),
('g6_2_soc_u1_review_a#25','soc',6,2,'u1','','g6_2_soc_u1_review_a','unit_review','SO6-2-u1-C4',4,'essay','teacher','관광객이 많이 찾아오는 해안 마을이 있어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 두 영향을 함께 고려한 해결 방법을 제안하세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C4","difficulty":4,"kind":"essay","stem":"관광객이 많이 찾아오는 해안 마을이 있어요. 관광이 마을에 주는 긍정적인 영향과 부정적인 영향을 하나씩 쓰고, 두 영향을 함께 고려한 해결 방법을 제안하세요.","answer_guide":{"answer":"예: 긍정적인 영향 — 숙소·식당 일자리가 생겨 마을 사람들의 소득이 늘어난다. 부정적인 영향 — 바닷가에 쓰레기가 쌓이고 바닷물이 오염된다. 제안 — 하루에 받는 관광객 수를 정하고 쓰레기를 되가져가게 하며, 해마다 한 달은 바닷가를 쉬게 해서 소득을 지키면서 오염을 줄인다.","scoring_points":["긍정적인 영향을 썼는가","부정적인 영향을 썼는가","두 영향을 함께 고려한 제안을 했는가"]},"explanation":["관광에는 두 영향이 함께 있어요.","한쪽만 보지 않아요.","좋은 점은 살리고 걱정은 줄여요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_review_b#1','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C1',1,'mc','auto','해발 고도가 높고 대체로 경사가 급한 지형의 갈래는 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u1-C1","difficulty":1,"kind":"mc","stem":"해발 고도가 높고 대체로 경사가 급한 지형의 갈래는 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"해안","mis":"SO6-2-u1-X03"},{"t":"하천","mis":"SO6-2-u1-X03"},{"t":"평야","mis":"SO6-2-u1-X03"}],"explanation":["높이 솟은 땅은 산지예요.","고원과 화산도 산지에 들어요.","하천은 물이 흐르는 곳이에요."]}'::jsonb),
('g6_2_soc_u1_review_b#2','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C4',1,'mc','auto','해안 지역에서 볼 수 있는 생활 모습은 어느 것인가요?',ARRAY['SO6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u1-C4","difficulty":1,"kind":"mc","stem":"해안 지역에서 볼 수 있는 생활 모습은 어느 것인가요?","options":[{"t":"물고기나 조개를 기르는 양식업","correct":true},{"t":"구리를 캐는 광업","mis":"SO6-2-u1-X03"},{"t":"수상 시장","mis":"SO6-2-u1-X03"},{"t":"파미르고원의 양 기르기","mis":"SO6-2-u1-X03"}],"explanation":["해안 주민들은 어업과 양식업을 해요.","항구·관광지·염전도 있어요.","광업은 산지, 수상 시장은 하천이에요."]}'::jsonb),
('g6_2_soc_u1_review_b#3','soc',6,2,'u1','','g6_2_soc_u1_review_b','unit_review','SO6-2-u1-C5',1,'sa','auto','세계의 기후를 구분하는 주된 기준은 기온과 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u1-C5","difficulty":1,"kind":"sa","stem":"세계의 기후를 구분하는 주된 기준은 기온과 무엇인가요? 세 글자로 쓰세요.","answer":["강수량"],"explanation":["기온은 덥고 추운 정도예요.","강수량은 비나 눈이 내린 양이에요.","이 둘로 기후를 나눠요."],"mis":"SO6-2-u1-X10"}'::jsonb),
