('g6_2_soc_u1_review_c#9','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C8',2,'mc','auto','여행 엽서 ㉰의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X13','SO6-2-u1-X14','SO6-2-u1-X11']::text[],false,'{"seq":9,"concept":"SO6-2-u1-C8","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉰의 곳에 나타나는 기후로 알맞은 것은 어느 것인가요?","options":[{"t":"냉대 기후","correct":true},{"t":"온대 기후","mis":"SO6-2-u1-X13"},{"t":"한대 기후","mis":"SO6-2-u1-X14"},{"t":"열대 기후","mis":"SO6-2-u1-X11"}],"explanation":["겨울이 길고 눈이 많이 와요.","침엽수림의 목재, 여름의 감자밭이 있어요.","냉대 기후의 생활이에요."],"asset":{"type":"passage","lines":["겨울이 끝없이 길어. 눈이 허리까지 쌓였어.","바늘잎나무 숲에서 벤 나무를 실은 트럭이 지나가.","짧은 여름에는 감자밭이 초록으로 물든대."],"title":"여행 엽서 ㉰"}}'::jsonb),
('g6_2_soc_u1_review_c#10','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',2,'mc','auto','여행 엽서 ㉵의 곳에 나타나는 기후와 생활을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X14','SO6-2-u1-X11','SO6-2-u1-X13']::text[],false,'{"seq":10,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"mc","stem":"여행 엽서 ㉵의 곳에 나타나는 기후와 생활을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"한대 기후 — 순록 유목과 오로라 관광","correct":true},{"t":"고산 기후 — 알파카 기르기","mis":"SO6-2-u1-X14"},{"t":"열대 기후 — 생태 관광","mis":"SO6-2-u1-X11"},{"t":"냉대 기후 — 올리브 재배","mis":"SO6-2-u1-X13"}],"explanation":["극지방 가까운 곳이에요.","오로라와 순록이 보여요.","한대 기후의 생활이에요."],"asset":{"type":"passage","lines":["극지방 가까운 곳이야. 밤하늘에 초록빛 오로라가 춤을 춰.","사람들은 이끼가 자라는 땅을 따라 순록 떼를 몰고 다녀.","오로라를 보러 온 여행객도 많아."],"title":"여행 엽서 ㉵"}}'::jsonb),
('g6_2_soc_u1_review_c#11','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C4',2,'mc','auto','관광의 긍정적인 영향으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"mc","stem":"관광의 긍정적인 영향으로 알맞은 것은 어느 것인가요?","options":[{"t":"관광객을 맞는 일자리가 생겨 소득이 늘어난다","correct":true},{"t":"바닷물이 오염된다","mis":"SO6-2-u1-X07"},{"t":"쓰레기가 쌓인다","mis":"SO6-2-u1-X07"},{"t":"마을이 시끄러워진다","mis":"SO6-2-u1-X07"}],"explanation":["관광은 좋은 점도 있어요.","일자리와 소득이 늘어요.","오염·쓰레기는 부정적인 영향이에요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_review_c#12','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C5',2,'ox','auto','적도 주변은 어디든 일 년 내내 더운 기후만 나타나요.',ARRAY['SO6-2-u1-X09']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"ox","stem":"적도 주변은 어디든 일 년 내내 더운 기후만 나타나요.","answer":"X","reason_options":[{"t":"적도 주변이라도 해발 고도가 높은 곳에는 서늘한 고산 기후가 나타나기 때문에","correct":true},{"t":"적도 주변은 모두 바닷가이기 때문에","mis":"SO6-2-u1-X09"}],"mis":"SO6-2-u1-X09","explanation":["적도 주변의 낮은 곳은 더워요.","높은 산지는 서늘한 고산 기후예요.","키토(에콰도르)가 예예요."]}'::jsonb),
('g6_2_soc_u1_review_c#13','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C9',2,'match','auto','기후와 그곳의 산업이나 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C9","difficulty":2,"kind":"match","stem":"기후와 그곳의 산업이나 일을 알맞게 이으세요.","pairs":[{"l":"한대 기후","r":"오로라·빙하 관광과 극지 연구"},{"l":"냉대 기후","r":"목재와 펄프 생산"},{"l":"열대 기후","r":"사파리 같은 생태 관광"}],"mis":"SO6-2-u1-X15","explanation":["기후마다 발달한 일이 달라요.","한대 — 관광·연구·자원 개발이에요.","냉대 — 숲, 열대 — 생태 관광이에요."]}'::jsonb),
('g6_2_soc_u1_review_c#14','soc',6,2,'u1','','g6_2_soc_u1_review_c','unit_review','SO6-2-u1-C6',2,'ox','auto','열대 기후 지역에는 열대 우림만 있고 초원은 없어요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C6","difficulty":2,"kind":"ox","stem":"열대 기후 지역에는 열대 우림만 있고 초원은 없어요.","answer":"X","reason_options":[{"t":"건기와 우기가 번갈아 나타나는 곳에는 초원이 넓게 펼쳐지기 때문에","correct":true},{"t":"열대 기후는 일 년 내내 비가 똑같이 오기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["열대 기후에도 경관이 여러 가지예요.","비가 늘 많으면 열대 우림이에요.","건기·우기가 번갈아 오면 초원이에요."]}'::jsonb),
