('g6_2_soc_u1_review_d#11','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',2,'ox','auto','섬을 쉬게 하면 오염만 줄고 일자리와 소득은 그대로예요.',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u1-C4","difficulty":2,"kind":"ox","stem":"섬을 쉬게 하면 오염만 줄고 일자리와 소득은 그대로예요.","answer":"X","reason_options":[{"t":"관광객이 줄면 오염과 함께 일자리와 소득도 줄기 때문에","correct":true},{"t":"섬을 쉬게 하면 관광객이 더 늘기 때문에","mis":"SO6-2-u1-X07"}],"mis":"SO6-2-u1-X07","explanation":["관광의 두 영향은 함께 움직여요.","관광객이 줄면 둘 다 줄어요.","그래서 신중하게 결정해요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_review_d#12','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C5',2,'mc','auto','적도를 기준으로 남반구와 북반구의 기후 분포가 비슷하게 나타나는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X08','SO6-2-u1-X10']::text[],false,'{"seq":12,"concept":"SO6-2-u1-C5","difficulty":2,"kind":"mc","stem":"적도를 기준으로 남반구와 북반구의 기후 분포가 비슷하게 나타나는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기후가 위도에 따라 달라지기 때문에","correct":true},{"t":"남반구와 북반구는 언제나 같은 날씨이기 때문에","mis":"SO6-2-u1-X08"},{"t":"기후가 나라 이름으로 정해지기 때문에","mis":"SO6-2-u1-X10"},{"t":"남반구에는 기후가 없기 때문에","mis":"SO6-2-u1-X10"}],"explanation":["같은 위도는 비슷한 햇볕을 받아요.","그래서 비슷한 기후가 나타나요.","적도를 기준으로 거울처럼 비슷해요."]}'::jsonb),
('g6_2_soc_u1_review_d#13','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',2,'match','auto','건조 기후의 두 곳과 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO6-2-u1-C7","difficulty":2,"kind":"match","stem":"건조 기후의 두 곳과 생활 모습을 알맞게 이으세요.","pairs":[{"l":"사막","r":"오아시스 주변에서 농사짓는다"},{"l":"초원","r":"가축을 데리고 옮겨 다닌다"}],"mis":"SO6-2-u1-X12","explanation":["건조 기후에는 사막과 초원이 있어요.","사막 — 오아시스 농사예요.","초원 — 유목과 이동식 가옥이에요."]}'::jsonb),
('g6_2_soc_u1_review_d#14','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',2,'ox','auto','같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타나요.',ARRAY['SO6-2-u1-X15']::text[],false,'{"seq":14,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"같은 기후 환경에서도 사람들의 생활 모습은 여러 가지로 나타나요.","answer":"O","reason_options":[{"t":"같은 기후 안에서도 지형과 비가 오는 모양, 사람들의 선택이 다르기 때문에","correct":true},{"t":"같은 기후면 생활도 모두 같기 때문에","mis":"SO6-2-u1-X15"}],"mis":"SO6-2-u1-X15","explanation":["같은 기후 칸에 여러 핀이 설 수 있어요.","온대 칸에는 핀이 셋 모였어요.","생활은 여러 가지예요."]}'::jsonb),
('g6_2_soc_u1_review_d#15','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C2',2,'ox','auto','산지는 해발 고도가 높고 경사가 급해 사람들이 전혀 이용하지 못해요.',ARRAY['SO6-2-u1-X04']::text[],false,'{"seq":15,"concept":"SO6-2-u1-C2","difficulty":2,"kind":"ox","stem":"산지는 해발 고도가 높고 경사가 급해 사람들이 전혀 이용하지 못해요.","answer":"X","reason_options":[{"t":"사람들은 산지에서 농사·목축·광업·관광을 하며 지형을 이용하기 때문에","correct":true},{"t":"산지에는 사람이 갈 수 없기 때문에","mis":"SO6-2-u1-X04"}],"mis":"SO6-2-u1-X04","explanation":["산지에서도 사람들은 살아가요.","지형을 이용하는 방법이 여러 가지예요.","계단식 농사·가축·광업·관광이에요."]}'::jsonb),
('g6_2_soc_u1_review_d#16','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',2,'ox','auto','판매할 곳이 바뀌면 상품에 넣을 알맞은 기능도 바뀔 수 있어요.',ARRAY['SO6-2-u1-X16']::text[],false,'{"seq":16,"concept":"SO6-2-u1-C10","difficulty":2,"kind":"ox","stem":"판매할 곳이 바뀌면 상품에 넣을 알맞은 기능도 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"곳마다 지형과 기후가 달라 사람들이 겪는 불편이 다르기 때문에","correct":true},{"t":"상품은 어느 곳에서나 같은 기능이면 충분하기 때문에","mis":"SO6-2-u1-X16"}],"mis":"SO6-2-u1-X16","explanation":["자연환경이 다르면 불편도 달라요.","그래서 맞는 기능도 달라요.","같은 특징이 있으면 같은 기능을 쓰기도 해요."]}'::jsonb),
('g6_2_soc_u1_review_d#17','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C1',3,'error','auto','같은 갈래의 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X01','SO6-2-u1-X02']::text[],false,'{"seq":17,"concept":"SO6-2-u1-C1","difficulty":3,"kind":"error","stem":"같은 갈래의 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「같은 갈래의 지형이면 경관 특징도 모두 같아.」","correct":true,"mis_target":"SO6-2-u1-X01"},{"t":"채원 — 「같은 산지라도 화산과 평평한 산은 모습이 달라.」","mis":"SO6-2-u1-X01"},{"t":"지민 — 「지형 경관은 그곳 사람들의 생활에 영향을 줘.」","mis":"SO6-2-u1-X02"}],"explanation":["같은 갈래 안에서도 특징이 갈려요.","마우나로아와 호라이마산은 둘 다 산지지만 달라요.","채원과 지민은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_review_d#18','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',3,'error','auto','열대·건조 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X11']::text[],false,'{"seq":18,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"error","stem":"열대·건조 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「건조 기후는 일 년 내내 기온 변화가 거의 없어.」","correct":true,"mis_target":"SO6-2-u1-X11"},{"t":"여울 — 「건조 기후는 낮과 밤의 기온 차이가 커.」","mis":"SO6-2-u1-X11"},{"t":"이준 — 「열대 기후는 일 년 내내 기온이 높아.」","mis":"SO6-2-u1-X11"}],"explanation":["기온 변화가 거의 없는 것은 열대 기후예요.","건조 기후는 낮밤의 기온 차이가 커요.","여울과 이준은 바르게 말했어요."]}'::jsonb),
('g6_2_soc_u1_review_d#19','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',3,'mc','auto','여행 엽서 ㉮의 집이 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12']::text[],false,'{"seq":19,"concept":"SO6-2-u1-C6","difficulty":3,"kind":"mc","stem":"여행 엽서 ㉮의 집이 바닥을 땅에서 띄운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"덥고 비가 자주 와 땅의 습기와 물을 피하려고","correct":true},{"t":"모래바람을 막으려고","mis":"SO6-2-u1-X12"},{"t":"추운 겨울에 땅의 냉기를 막으려고","mis":"SO6-2-u1-X12"},{"t":"물과 풀을 찾아 옮기기 쉽게 하려고","mis":"SO6-2-u1-X12"}],"explanation":["일 년 내내 덥고 소나기가 와요.","땅이 늘 축축해요.","바닥을 띄운 고상 가옥으로 피해요."],"asset":{"type":"passage","lines":["이곳은 일 년 내내 덥고 거의 날마다 소나기가 와.","키 큰 나무가 빽빽한 숲 사이로 바닥을 땅에서 띄운 집이 보여.","마을 사람들은 큰 농장에서 카카오를 기른대."],"title":"여행 엽서 ㉮"}}'::jsonb),
('g6_2_soc_u1_review_d#20','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C7',3,'mc','auto','열대 기후와 건조 기후의 집이 다른 까닭을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u1-X12','SO6-2-u1-X11']::text[],false,'{"seq":20,"concept":"SO6-2-u1-C7","difficulty":3,"kind":"mc","stem":"열대 기후와 건조 기후의 집이 다른 까닭을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"열대는 바람을 들이고 습기를 피해야 하고, 사막은 햇볕과 모래바람을 막아야 하기 때문에","correct":true},{"t":"두 지역 사람들의 좋아하는 색이 달라서","mis":"SO6-2-u1-X12"},{"t":"두 지역의 기온과 강수량이 같아서","mis":"SO6-2-u1-X11"},{"t":"집을 아무렇게나 지어서","mis":"SO6-2-u1-X12"}],"explanation":["기후가 다르면 막을 것과 들일 것이 달라요.","열대 — 큰 창, 띄운 바닥이에요.","사막 — 두꺼운 벽, 작은 창이에요."]}'::jsonb),
('g6_2_soc_u1_review_d#21','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C10',3,'ox','auto','상품 판매 계획은 나라를 정한 뒤 지형과 기후를 조사하고, 아이디어를 이야기해 계획을 세워요.',ARRAY['SO6-2-u1-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u1-C10","difficulty":3,"kind":"ox","stem":"상품 판매 계획은 나라를 정한 뒤 지형과 기후를 조사하고, 아이디어를 이야기해 계획을 세워요.","answer":"O","reason_options":[{"t":"자연환경을 먼저 알아야 그곳에 필요한 상품을 떠올릴 수 있기 때문에","correct":true},{"t":"상품부터 정하고 나라는 마지막에 정하기 때문에","mis":"SO6-2-u1-X17"}],"mis":"SO6-2-u1-X17","explanation":["나라를 먼저 정해요.","자연환경을 조사해요.","그 위에서 아이디어를 내요."]}'::jsonb),
('g6_2_soc_u1_review_d#22','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C4',3,'error','auto','관광이 늘어난 섬을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u1-X07']::text[],false,'{"seq":22,"concept":"SO6-2-u1-C4","difficulty":3,"kind":"error","stem":"관광이 늘어난 섬을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「일자리가 늘었으니 바다가 더러워져도 괜찮아.」","correct":true,"mis_target":"SO6-2-u1-X07"},{"t":"예나 — 「일자리도 늘었지만 쓰레기도 늘었어.」","mis":"SO6-2-u1-X07"},{"t":"도현 — 「두 영향을 함께 따져 정해야 해.」","mis":"SO6-2-u1-X07"}],"explanation":["한쪽 영향만 보면 다른 쪽 문제가 커져요.","관광에는 두 영향이 함께 있어요.","예나와 도현은 바르게 말했어요."],"asset":{"type":"passage","lines":["어느 섬의 해안에 관광객이 해마다 늘었다.","섬 사람들은 숙소와 식당에서 일할 자리가 생겨 벌이가 늘었다.","그런데 바닷가에 쓰레기가 쌓이고 바닷물이 더러워졌다.","섬은 한동안 관광객을 받지 않고 섬을 쉬게 하기로 했다."],"title":"관광이 늘어난 섬"}}'::jsonb),
('g6_2_soc_u1_review_d#23','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C3',4,'mc','auto','여행 엽서 ㉴의 곳과 같은 지형에서 볼 수 있는 생활 모습을 모두 바르게 고른 것은 어느 것인가요?',ARRAY['SO6-2-u1-X06','SO6-2-u1-X03']::text[],false,'{"seq":23,"concept":"SO6-2-u1-C3","difficulty":4,"kind":"mc","stem":"여행 엽서 ㉴의 곳과 같은 지형에서 볼 수 있는 생활 모습을 모두 바르게 고른 것은 어느 것인가요?","options":[{"t":"수상 시장 · 평야의 큰 규모 농사 · 수력 발전 · 어업","correct":true},{"t":"수상 시장 · 염전 · 항구","mis":"SO6-2-u1-X06"},{"t":"계단식 농사 · 광업 · 스키장","mis":"SO6-2-u1-X03"},{"t":"오아시스 농사 · 유목","mis":"SO6-2-u1-X03"}],"explanation":["㉴는 하천 지형이에요.","하천은 물길·평야·물의 힘·물고기를 줘요.","염전·항구는 해안, 계단식 농사는 산지예요."],"asset":{"type":"passage","lines":["강을 따라 내려가니 배들이 물 위에 모여 있었어.","배 위에서 과일과 채소를 사고팔고 있었어.","강가에는 강물이 날라 온 흙으로 넓은 들이 펼쳐져."],"title":"여행 엽서 ㉴"}}'::jsonb),
('g6_2_soc_u1_review_d#24','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C6',4,'essay','teacher','여행 엽서 ㉮와 ㉲의 곳은 기후가 서로 달라요. 두 곳의 기후 이름과 특징을 쓰고, 그 기후에 맞춘 집 모습을 견주어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u1-C6","difficulty":4,"kind":"essay","stem":"여행 엽서 ㉮와 ㉲의 곳은 기후가 서로 달라요. 두 곳의 기후 이름과 특징을 쓰고, 그 기후에 맞춘 집 모습을 견주어 쓰세요.","answer_guide":{"answer":"예: ㉮는 일 년 내내 덥고 비가 자주 오는 열대 기후이고, ㉲는 비가 아주 조금 와서 풀이 낮게 자라는 건조 기후의 초원이다. ㉮에서는 땅의 습기를 피하고 바람이 통하게 바닥을 땅에서 띄운 집을 짓고, ㉲에서는 물과 풀을 찾아 옮겨 다니기 때문에 접었다 폈다 할 수 있는 천막집에서 산다.","scoring_points":["두 곳의 기후 이름을 바르게 썼는가","두 기후의 특징을 썼는가","기후에 맞춘 집 모습을 견주어 썼는가"]},"explanation":["㉮ — 열대, ㉲ — 건조 초원이에요.","기후가 집 모습을 정해요.","띄운 바닥 vs 이동식 천막이에요."],"asset":{"type":"passage","lines":["이곳은 일 년 내내 덥고 거의 날마다 소나기가 와.","키 큰 나무가 빽빽한 숲 사이로 바닥을 땅에서 띄운 집이 보여.","마을 사람들은 큰 농장에서 카카오를 기른대."],"title":"여행 엽서 ㉮"}}'::jsonb),
('g6_2_soc_u1_review_d#25','soc',6,2,'u1','','g6_2_soc_u1_review_d','unit_review','SO6-2-u1-C9',4,'essay','teacher','추운 기후로 가는 두 길을 설명하고, 각 길에서 만나는 기후 지역의 생활 모습을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u1-C9","difficulty":4,"kind":"essay","stem":"추운 기후로 가는 두 길을 설명하고, 각 길에서 만나는 기후 지역의 생활 모습을 하나씩 쓰세요.","answer_guide":{"answer":"예: 첫째 길은 적도에서 북쪽이나 남쪽으로 아주 멀리 고위도로 가는 것으로, 남극과 북극 주변의 한대 기후 지역에 닿는다. 이곳 사람들은 이끼가 자라는 곳에서 순록을 기르며 옮겨 다닌다. 둘째 길은 적도 주변이라도 높은 산 위로 오르는 것으로, 일 년 내내 서늘한 고산 기후 지역에 닿는다. 이곳 사람들은 알파카와 라마를 기르고 감자를 재배한다.","scoring_points":["고위도로 가는 길과 높이 오르는 길을 설명했는가","한대·고산 기후를 바르게 짝지었는가","각 기후의 생활 모습을 하나씩 썼는가"]},"explanation":["길 하나 — 고위도 → 한대예요.","길 둘 — 높은 산 → 고산이에요.","생활 모습도 달라요."],"asset":{"type":"passage","lines":["길 하나 — 적도에서 북쪽으로 아주 멀리 간다 → 겨울이 길고 기온이 매우 낮은 기후","길 둘 — 적도 주변에서 높은 산 위로 오른다 → 일 년 내내 서늘한 기후"],"title":"추운 기후로 가는 두 길"}}'::jsonb)
